insert into public.posts (slug, title, category_slug, excerpt, reading_time, date, author_name, author_role, guest_author, related, status, body, sort_order) values
  ('first-week-after-a-layoff', 'What to do in your first week after a layoff', 'guides', 'A calm, ordered checklist for the first seven days, so the urgent things get handled and the rest can wait.', '6 min read', null, null, null, null, ARRAY['negotiating-your-severance', 'rebuild-your-resume-after-a-layoff']::text[], 'published', '[{"type":"p","runs":["Before anything else: a layoff is a budget decision, not a verdict on your worth. You do not need to have a plan by Friday. You need to protect a few things that are easy to handle now and painful to fix later. Work down this list and then give yourself permission to rest."]},{"type":"h2","text":"1. Take 48 hours before you sign anything"},{"type":"p","runs":["You will likely be handed a separation agreement and asked to sign quickly. You almost never have to sign on the spot. In the US, if you are 40 or older, you are generally entitled to at least 21 days to consider a severance agreement and 7 days to revoke after signing. Ask for the deadline in writing, and use the time."]},{"type":"h2","text":"2. Save everything before access is cut"},{"type":"p","runs":["Company accounts often disappear within hours. While you still have access, capture what is yours to keep:"]},{"type":"list","ordered":false,"items":[["Your personal contacts, references, and any non-confidential work samples you are permitted to keep."],["A copy of your most recent reviews, wins, and metrics, the raw material for your resume."],["Your benefits and payroll documents, plus the HR contact who can answer questions next week."],["Forward anything you need to a personal email before your accounts are deactivated."]]},{"type":"callout","runs":["Only take what is genuinely yours. Confidential data, customer lists, and proprietary code stay behind. The goal is your own record, not risk."],"title":"One rule"},{"type":"h2","text":"3. Map your runway in real numbers"},{"type":"p","runs":["Anxiety thrives on vagueness. Replace it with a number. Add up your savings plus any severance, then divide by your real monthly spend. That figure, how many months you have, is the single most useful thing you can know this week. It tells you whether you are negotiating from comfort or urgency, and it makes every later decision less abstract."]},{"type":"p","runs":["If you would rather not build the spreadsheet, Offboard''s Financial Runway Calculator does it for you. Enter savings, severance, and monthly expenses and it shows the months you have left, all calculated privately in your browser, with no AI and nothing shared."]},{"type":"h2","text":"4. File for unemployment now"},{"type":"p","runs":["File in your state the week you are let go, even if you received severance. Benefits can take weeks to start, and in many states a layoff qualifies you regardless of severance. Waiting only delays money you are entitled to."]},{"type":"h2","text":"5. Decide what happens to health coverage"},{"type":"p","runs":["Find out exactly when your current coverage ends. Then compare your options before the deadline: COBRA continuation, a spouse or partner''s plan, or a marketplace plan (a job loss opens a special enrollment window). COBRA is often the most expensive path, so price the alternatives before defaulting to it."]},{"type":"h2","text":"6. Tell a small circle, then pause the announcement"},{"type":"p","runs":["Let a few trusted people know early, the ones who will think of you when they hear of a role. You do not need a polished public post in week one. Word of mouth from people who know your work moves faster than a broadcast, and you can announce more widely once you have your footing."]},{"type":"h2","text":"What can wait until week two"},{"type":"list","ordered":false,"items":[["Rewriting your whole resume, do the outcomes capture above first, polish later."],["Applying to dozens of roles, a scattered week-one spray rarely lands."],["Big career-pivot decisions, make those with a clear head and a known runway."]]},{"type":"p","runs":["Handle the protective list, then stop. A sustainable search is a marathon, and the people who land well are usually the ones who did not burn out in the first week trying to do everything at once."]}]'::jsonb, 0),
  ('negotiating-your-severance', 'How to read and negotiate your severance', 'guides', 'What is actually negotiable, the questions to ask before you sign, and how to buy yourself more runway.', '7 min read', null, null, null, null, ARRAY['first-week-after-a-layoff', 'career-changers-guide-to-job-offer-negotiations']::text[], 'published', '[{"type":"p","runs":["Nothing here is legal advice, and for a large package or anything that feels off it is worth a one-time consult with an employment attorney. But you can do a lot of the groundwork yourself by understanding what the document is actually trading."]},{"type":"h2","text":"What you are actually signing"},{"type":"p","runs":["In most severance agreements, the company offers money and continued benefits in exchange for a few things from you, usually a release of legal claims, sometimes a non-disparagement clause, and occasionally restrictions on where you can work next. The money is the consideration for what you give up. That framing matters: if they want your signature, you have leverage to shape the terms."]},{"type":"h2","text":"Read these clauses closely before anything else"},{"type":"list","ordered":false,"items":[["The release: what claims you are waiving, and whether it is mutual."],["Non-compete and non-solicit: how broad, how long, and whether they could limit your next job."],["Non-disparagement: is it one-sided, or does the company agree to the same?"],["Benefits end date and how severance interacts with unemployment in your state."],["Confidentiality: whether you can even discuss the terms, and any carve-outs you need."]]},{"type":"callout","runs":["If you are 40 or older, you generally get at least 21 days to consider the agreement and 7 days to revoke after signing. Confirm your deadline in writing and do not let urgency pressure you into same-day signature."],"title":"Watch the deadline, not the clock"},{"type":"h2","text":"Where the room usually is"},{"type":"p","runs":["Severance is rarely just one number. When more weeks of pay are not on the table, other terms often are, and several of them convert directly into runway or a smoother search:"]},{"type":"list","ordered":false,"items":[["More weeks of pay, the obvious one, especially if your tenure exceeds the formula offered."],["Extended health coverage, or the company covering COBRA premiums for a set number of months."],["Accelerated or extended equity vesting, which can be worth more than extra salary weeks."],["A defined, agreed reference or a neutral confirmation of your dates and title."],["Keeping your laptop, phone, or a professional certification the company was funding."],["Loosening a non-compete so it does not block the roles you would realistically pursue."]]},{"type":"h2","text":"How to make the ask"},{"type":"p","runs":["Tone wins here. You are not in a fight, you are proposing terms that let everyone move on cleanly. Lead with appreciation, anchor to something concrete, and ask in writing so there is a record. A simple structure works:"]},{"type":"list","ordered":false,"items":[["Acknowledge the offer and thank them for it."],["Name a specific, reasoned request, for example two additional weeks given your time on the team."],["Tie it to a fact: tenure, an unvested grant, a project you are leaving in good shape."],["Make it easy to say yes, propose the exact revised terms rather than a vague ''more''."]]},{"type":"h2","text":"Before you sign"},{"type":"p","runs":["Run a final pass: confirm every promise is in the written document (verbal assurances do not survive), check the benefits and final-pay dates against your runway, and make sure nothing restricts your next move more than you realized. Once the terms are right, signing is the easy part, and you will start the search knowing exactly how much time you bought yourself."]},{"type":"callout","runs":["You can store your agreement in Offboard''s Documents and run a private AI analysis that explains the key terms in plain language, the release, the non-compete, the deadlines, so nothing important hides in the legalese. It stays in your private career memory, never shared with anyone."],"title":"Read it with a second set of eyes"}]'::jsonb, 1),
  ('rebuild-your-resume-after-a-layoff', 'Rebuild your resume after a layoff', 'guides', 'How to frame the layoff, lead with outcomes, and tailor a base resume to each role without starting over every time.', '8 min read', null, null, null, null, ARRAY['first-week-after-a-layoff', 'how-ai-is-changing-the-job-search-in-2026']::text[], 'published', '[{"type":"h2","text":"First, settle how you talk about the layoff"},{"type":"p","runs":["Layoffs are common and recruiters know it. You do not owe an explanation on the resume itself. Keep your dates honest, and if you want context, a short, neutral line in a cover note or LinkedIn is plenty: a role eliminated in a company-wide reduction is a fact, not a flaw. Spend your energy on the work you did, not on defending the exit."]},{"type":"h2","text":"Build one strong base resume"},{"type":"p","runs":["Trying to keep ten slightly different resumes in sync is how things go stale. Instead, build a single, complete base, then tailor a copy per role. Your base should include:"]},{"type":"list","ordered":false,"items":[["A short header that names the role you are targeting, not a generic title."],["Every relevant role with dates, scope, and the size of what you owned."],["A deep bank of accomplishment bullets, more than any one application needs."],["Skills and tools stated plainly, so both humans and keyword filters can find them."]]},{"type":"h2","text":"Lead with outcomes, not duties"},{"type":"p","runs":["The difference between a forgettable bullet and a strong one is whether it shows a result. A duty describes what you were assigned. An outcome shows what changed because you were there. Use a simple shape: action, then impact, then a number wherever you honestly can."]},{"type":"callout","runs":["Weak: “Responsible for managing the onboarding process.” Strong: “Redesigned onboarding, cutting time-to-first-value from 14 days to 5 and lifting 30-day retention 12%.”"],"title":"Weak vs. strong"},{"type":"p","runs":["Do not have clean metrics for everything? That is fine. Reach for scale (how many, how large), speed (how much faster), or quality (fewer errors, higher satisfaction). A credible directional result beats a vague responsibility every time."]},{"type":"h2","text":"Tailor each application without starting over"},{"type":"p","runs":["Tailoring is not rewriting. With a strong base, each application is mostly selection and emphasis:"]},{"type":"list","ordered":false,"items":[["Read the job description and note the 5 to 8 things it clearly cares about most."],["Pull the bullets from your base that speak to those priorities, and cut the rest."],["Echo the role''s own language for skills you genuinely have, so filters and skimmers catch them."],["Reorder so the most relevant experience sits highest on the page."]]},{"type":"p","runs":["Most applicant tracking systems and recruiters scan, they do not read. Tailoring is how you make the relevant ten seconds count, and a base-plus-selection workflow makes it a five-minute job instead of an evening."]},{"type":"h2","text":"Avoid the common traps"},{"type":"list","ordered":false,"items":[["Stuffing keywords you cannot back up, it falls apart in the interview."],["A dense wall of text, white space and short bullets get read."],["Listing duties for senior roles, at that level, impact is the whole point."],["One resume for every job, generic reads as generic."]]},{"type":"h2","text":"Keep it a living document"},{"type":"p","runs":["Your resume is not a one-time artifact, it is a record you maintain. As outcomes land in the search, callbacks, projects, new metrics, fold them back into the base so the next tailored copy is even stronger. This is exactly the loop Offboard is built around: upload your resume once, then let Resume Tailor reshape it for each role, or paste a job URL and an Application Packet tailors your resume, drafts the cover letter, and preps the interview in one pass, always starting from everything you have already done rather than a blank page."]}]'::jsonb, 2),
  ('career-changers-guide-to-job-offer-negotiations', 'The Career Changer''s Guide to Job Offer Negotiations', 'guides', 'How to negotiate your worth when you''re changing careers, and why most people leave money on the table. Expert strategies from the cofounders of YourNegotiations.', '8 min read', '2026-03-18', 'Offboard', 'Team', '{"name":"Gerta & Alex","bio":"Cofounders of YourNegotiations.com. They help professionals negotiate job offers with confidence. Their clients have negotiated millions in additional compensation across tech, finance, and consulting.","company":"YourNegotiations","url":"https://yournegotiations.com"}'::jsonb, ARRAY['negotiating-your-severance', 'rebuild-your-resume-after-a-layoff']::text[], 'published', '[{"type":"p","runs":["Changing careers doesn''t automatically mean you''ll have to take a pay cut, even though a lot of high performers assume it does."]},{"type":"p","runs":["We''re in a peculiar job market. Yes it''s competitive, but it can be surprisingly unpredictable. For instance, several of our clients have received initial job offers at a lower title or level than at their last job, at comparable companies, but we''ve been able to help them negotiate compensation packages that are even higher than what they were making before. Old assumptions like “changing careers automatically means taking a step back financially” are no longer true."]},{"type":"p","runs":["We see these assumptions often held especially by people moving from finance, consulting, or big tech into new fields they''re genuinely excited about. But because they don''t check every box in the job description, they start the process already feeling like they should be flexible, grateful, or cautious about pushing too hard when negotiating their offers."]},{"type":"p","runs":["This mindset tends to show up early in the job search, sometimes without them even realizing it. And once they start interviewing, it impacts how negotiations unfold later."]},{"type":"p","runs":["The good news is that a career pivot doesn''t erase your leverage. But you do need to be thoughtful about how you carry yourself through the process."]},{"type":"divider"},{"type":"h2","text":"Laying the groundwork early","id":"laying-the-groundwork-early"},{"type":"p","runs":["A common misconception is that you start negotiating when the company extends an offer. However, you start shaping your future compensation far before that, sometimes as early as the online application itself when you''re asked for your preferred compensation."]},{"type":"p","runs":["Here are a few things we strongly recommend that career changers keep in mind throughout the job search."]},{"type":"h2","text":"Be careful with early compensation questions","id":"be-careful-with-early-compensation-questions"},{"type":"p","runs":["Sharing your preferred salary number will never help you, except in very rare edge cases."]},{"type":"p","runs":["Imagine that negotiations are like a game of cards, and the cards in your hand are your leverage. Your preferred salary number is a powerful card, and it''s hard to win the game by revealing it. The company has their own cards too, such as the “true max budget for this role” card, and they will never proactively reveal their cards either."]},{"type":"p","runs":["Note that in many US states, companies are mandated by law to share their salary range on job postings. These salary ranges are not truthful, as most companies follow the letter of the law but not the spirit of the law."]},{"type":"p","runs":["So if you share your number first, it will either:"]},{"type":"list","ordered":false,"items":[[{"b":["Fall below the top of their budget."]}," ","And they may agree to it, but you''ve now left money on the table, because the company knows that you''d be open to accepting less than what they''ve budgeted for."],[{"b":["Fall above the top of their budget."]}," ","This introduces risk that they think you''re entitled, can''t afford you, or feel that you''re too far apart that you won''t be happy in the role even if you did accept."]]},{"type":"p","runs":["Some more reasons why sharing a number first is risky:"]},{"type":"list","ordered":false,"items":[[{"b":["Limits your bargaining power:"]}," ","If you share your number upfront, you may be limiting your bargaining power later in the negotiation process. Once you''ve disclosed your desired salary, the company may be less willing to negotiate higher than that figure."],[{"b":["Lack of information:"]}," You may not have all the information you need to make an informed decision about your desired compensation until later in the interview process."],[{"b":["Perception of being inflexible:"]}," ","If you share a number upfront, especially if it ends up being far above their budget, you may be perceived as inflexible or difficult to work with."],[{"b":["Different compensation structures:"]}," ","Different companies may have different structures, including stock options versus shares, vesting periods and cliffs, bonus types, commission-based pay, and more. Sharing a number doesn''t capture these complexities."]]},{"type":"p","runs":["On that note, sharing a range is very similar to sharing a number, because when you share a range, you''re implying the bottom of your range is an acceptable amount to you. So we recommend not sharing a range either."]},{"type":"blockquote","runs":["If you''re asked for a number or range early on, tactfully deflect and instead say something like: “Thank you for asking! I''m currently focused on exploring that this is a mutually good fit. I''m confident we can align on compensation.”"]},{"type":"p","runs":["There are many ways you can phrase deflections, and much of it depends on your unique circumstances, whether you''re in between jobs or currently working, the company culture, the demeanor of the recruiter, if you were referred, whether you have an existing relationship with the hiring manager, and more."]},{"type":"divider"},{"type":"h2","text":"Avoid oversharing in general","id":"avoid-oversharing"},{"type":"p","runs":["What makes someone a great employee in most jobs nowadays but also makes them bad at negotiations? ",{"b":["Oversharing."]}]},{"type":"p","runs":["It''s virtually guaranteed that you''ll get pushback from the company whenever you refrain from sharing something."]},{"type":"p","runs":["That includes your current or past compensation, the details of other offers you''ve received, or other opportunities you''re considering. Note: it''s illegal in many US states for employers to ask for your salary history."]},{"type":"p","runs":["Being transparent can feel collaborative, but it often gives away information that''s hard to take back. Overcommunication is a common trait shared by high performers, but it can work against you in a negotiation."]},{"type":"divider"},{"type":"h2","text":"Negotiating well signals that you''d make a strong hire","id":"negotiating-well-signals-a-strong-hire"},{"type":"p","runs":["Being overly transparent comes at another cost. You may think you''re being trusting and collaborative, but it can also signal that you cave under pressure, you may be too people-pleasing, you may not know how and when to be strategic, and you may not have the skills needed to handle challenging conversations, all of which are important traits companies look for when hiring."]},{"type":"p","runs":["Imagine that you accepted the first offer a company made you without negotiating. It could get the hiring manager thinking, “This candidate just said yes to the first offer. Is this how they''re going to handle their work with cross-functional teams, business partners, external vendors, investors?”"]},{"type":"blockquote","runs":["Many years ago, Gerta negotiated her job offer against a tough and driven hiring manager. Once Gerta started the job, that manager put her in charge of the team''s most important projects, telling her, “I remember how you negotiated your offer, so I trust you to lead this work.”"]},{"type":"divider"},{"type":"h2","text":"Negotiating your offer","id":"negotiating-your-offer"},{"type":"p","runs":["Negotiating your offer well doesn''t happen in a vacuum during the job search. It also reflects how your manager and team will perceive you in the job, as someone with competence and strong business acumen."]},{"type":"h2","text":"Always show excitement for the role","id":"always-show-excitement"},{"type":"p","runs":["You can never show too much enthusiasm. We''ve sometimes been asked, “If I show too much enthusiasm, doesn''t that make me seem desperate for the job and thus lose leverage?” or “I have multiple offers, isn''t it better to play hard to get and pit the companies against each other when negotiating?”"]},{"type":"p","runs":[{"b":["No."]}," Companies want to hire people who will be excited to work there. That means you''ll be motivated in the job, onramp quickly, and be a pleasant co-worker to work alongside. If you''re playing it cool, a company may interpret that as you not being fully committed, that you''re using them as leverage for another opportunity, or that you won''t be a good culture fit."]},{"type":"p","runs":["Showing enthusiasm is even more important in today''s tough job market. Competition for roles is especially tough, and many jobs are getting hundreds, if not thousands, of applicants. By the time a company has whittled down to a final list of candidates, every candidate on that list more than meets the qualifications. So what''s the differentiator? At that point, it often comes down to whether they think they''ll like working with you."]},{"type":"divider"},{"type":"h2","text":"On mindset: you have more leverage than you may think","id":"you-have-more-leverage-than-you-think"},{"type":"p","runs":["Unfortunately, the norms around the recruiting and negotiation process naturally favor employers because job applicants assume that the companies hold all the cards. This can feel truer if you''re switching career tracks and feel brand new to the industry."]},{"type":"p","runs":["But remember, you as a competitive candidate have leverage too, with your experience, qualifications, and optionality (i.e. you should always apply to multiple roles when job searching; never just one at a time)."]},{"type":"p","runs":["Negotiating may feel risky, but reframing the process for yourself can have you show up in all your conversations from a more empowered state of mind. You''re not asking a company for favors, you''re exploring together to find a win-win deal for all parties involved."]},{"type":"divider"},{"type":"h2","text":"More resources","id":"more-resources"},{"type":"p","runs":["Changing careers can feel like you''re starting over, but don''t let this move convince you that you don''t have leverage."]},{"type":"p","runs":["For more tips and resources:"]},{"type":"list","ordered":false,"items":[[{"b":[{"a":{"text":"Free 1:1 call","href":"https://yournegotiations.com/call"}}]}," ","- If you''re job searching or facing upcoming negotiations, book a free call with Alex for tailored advice for your situation."],[{"b":[{"a":{"text":"Free transition doc","href":"https://yournegotiations.kit.com/transitiondoc"}}]}," ","- If you''re leaving your job soon, download our free template to organize and hand off your work to your backfills (your coworkers will thank you!)."],[{"b":[{"a":{"text":"Newsletter","href":"https://yournegotiations.com/newsletter"}}]}," ","- Subscribe to our weekly negotiation newsletter."],[{"b":[{"a":{"text":"Podcast","href":"https://yournegotiations.com/podcast"}}]}," ","- Listen to ",{"i":["Gentle Power"]},", our weekly podcast on power and negotiations."],[{"b":[{"a":{"text":"Website","href":"https://yournegotiations.com"}}]}," ","- Check out YourNegotiations.com for more negotiation resources."],[{"b":["$250 referral bonus"]}," - Refer a friend and get $250 if they work with us. Just send an email intro to"," ",{"a":{"text":"alex@yournegotiations.com","href":"mailto:alex@yournegotiations.com"}},"."," ",{"a":{"text":"Learn more about our referral program here","href":"https://yournegotiations.com/referral"}},"."]]}]'::jsonb, 3),
  ('health-insurance-after-a-layoff', 'Health insurance after a layoff: COBRA, ACA, and the cheaper options people miss', 'guides', 'Most laid-off workers default to COBRA and overpay. A clear, 30-minute comparison of every coverage option and how to choose before the deadline.', '7 min read', '2026-06-04', 'Offboard', 'Team', null, ARRAY['first-week-after-a-layoff', 'negotiating-your-severance']::text[], 'published', '[{"type":"p","runs":["Losing your job usually means losing your health insurance within a few weeks. The good news is you have more options than COBRA, and most people who default to COBRA could have paid far less for similar or better coverage. Here is the short, practical comparison, plus how to decide before the clock runs out."]},{"type":"h2","text":"First, find your exact coverage end date"},{"type":"p","runs":["Some employers end coverage on your last day of work. Others run it through the end of the month, and a few extend it as part of severance. Ask HR in writing for the exact date your medical, dental, and vision coverage ends. Every option below has a deadline tied to that date."]},{"type":"h2","text":"Option 1: A spouse or partner''s plan"},{"type":"p","runs":["If your spouse, domestic partner, or parent (if you are under 26) has employer coverage, losing your job triggers a special enrollment window of usually 30 to 60 days. This is almost always the cheapest path because the other employer is subsidizing the premium. Ask their HR what documentation they need (typically a letter from your old employer confirming the coverage end date)."]},{"type":"h2","text":"Option 2: An ACA marketplace plan"},{"type":"p","runs":["A layoff opens a 60-day special enrollment period on healthcare.gov or your state exchange. For most laid-off workers this is the best value, because the same income drop that ended your job also makes you eligible for subsidies you could not get while employed."]},{"type":"list","ordered":false,"items":[["Estimate your household income for the rest of the calendar year, not your old salary. If you expect to be on unemployment for several months, your subsidy will be much larger than the calculator first suggests."],["Compare on total cost, not just premium. A cheaper Bronze plan with a $7,000 deductible can cost more than a Silver plan if you actually use care."],["If you take any prescriptions, check each plan''s formulary before enrolling. The same drug can be free on one plan and hundreds of dollars on another."]]},{"type":"callout","runs":["Through 2025, enhanced ACA subsidies cap premiums at roughly 8.5% of income for most households. After that, rules may shift, so check current subsidy levels when you enroll."],"title":"Worth knowing"},{"type":"h2","text":"Option 3: COBRA continuation"},{"type":"p","runs":["COBRA lets you keep your exact employer plan for up to 18 months. The catch is price. You now pay the full premium plus a 2% admin fee, which usually lands somewhere between $600 and $900 a month for an individual and $1,800 to $2,500 for a family. That is often four to eight times what a comparable ACA plan would cost with subsidies."]},{"type":"p","runs":["COBRA is genuinely the right answer in three cases: you are mid-treatment and cannot change networks, you have already hit your deductible for the year, or your employer is paying for COBRA as part of severance. You also have 60 days from your coverage end date to elect COBRA, and it backdates, so you can wait, see if you need care, and elect retroactively if something happens."]},{"type":"h2","text":"Option 4: A short-term or catastrophic plan"},{"type":"p","runs":["Short-term medical plans are cheap but exclude pre-existing conditions and many essential services. Useful only if you are healthy, expect to land a new job within a few months, and want a thin safety net. Treat it as a stopgap, not a real plan."]},{"type":"h2","text":"Option 5: Medicaid"},{"type":"p","runs":["If your income drops far enough, you may qualify for Medicaid in your state. Eligibility is based on current monthly income, not last year''s, so applying right after a layoff is often a different answer than applying while employed. There is no annual enrollment window for Medicaid, you can apply any time."]},{"type":"h2","text":"How to decide in 30 minutes"},{"type":"list","ordered":true,"items":[["Confirm your coverage end date with HR in writing."],["Check if you can join a spouse, partner, or parent''s plan first."],["If not, get an ACA quote at healthcare.gov with your projected post-layoff income, not your old salary. Compare total cost, not premium."],["If you are mid-treatment or have hit your deductible, price COBRA against the ACA alternative for the months you actually need."],["If your income is very low, check Medicaid eligibility for your state."]]},{"type":"callout","runs":["For most laid-off workers, an ACA marketplace plan with subsidies is cheaper than COBRA, often by hundreds of dollars a month. Always price both before defaulting."],"title":"The point"},{"type":"p","runs":["Health insurance is one line on Offboard''s Financial Runway calculator, but it is usually the single biggest swing in your monthly budget. Get this number right and the rest of your runway plan gets noticeably easier."]}]'::jsonb, 4),
  ('how-to-announce-a-layoff-on-linkedin', 'How to announce a layoff on LinkedIn (with three templates)', 'guides', 'When to post, what to say, and three templates you can adapt. Plus the small things that meaningfully raise the response rate.', '6 min read', '2026-06-04', 'Offboard', 'Team', null, ARRAY['first-week-after-a-layoff', 'rebuild-your-resume-after-a-layoff']::text[], 'published', '[{"type":"p","runs":["You do not have to post anything on LinkedIn after a layoff. But if you decide to, a good post is one of the highest-leverage hours you will spend in your search. It puts your situation in front of hundreds of people who already know your work and may quietly route an opportunity to you within days. Here is how to write one that lands, plus three templates you can adapt."]},{"type":"h2","text":"Should you post at all?"},{"type":"p","runs":["Post if any of these are true: you have a strong professional network on LinkedIn, you are open about looking, you can write the post without anger or pleading, and you can stay offline for a few hours after publishing while it gathers comments."]},{"type":"p","runs":["Wait if you are still in shock, mid-negotiation on severance, bound by a non-disparagement clause you have not read carefully, or planning to take a real break before searching. There is no expiration date on this. A post a month from now works as well as a post tomorrow."]},{"type":"h2","text":"What a good post does"},{"type":"list","ordered":false,"items":[["Names the situation in one calm sentence. No drama, no company-bashing."],["Says what you do well, in specific terms. Not ''product leader'', but ''product leader who shipped two zero-to-one B2B SaaS products and grew the second from $0 to $4M ARR in 18 months''."],["Says what you are looking for, with enough specificity that someone could match you to a role. Function, industries, location or remote, level."],["Makes it easy to help. A clear ask (intros, leads, referrals), an email address, and a green Open to Work frame on your photo if you are open about searching."],["Ends with thanks, not desperation."]]},{"type":"callout","runs":["Avoid the lines recruiters and your network have read a thousand times: humbled, blessed, grateful for the journey, excited for the next chapter. Be a person, not a press release."],"title":"One rule above all"},{"type":"h2","text":"Template 1: The clean and direct version"},{"type":"blockquote","runs":["News: I was laid off from [Company] last week as part of a broader reduction.",{"br":true},{"br":true},"For the last [X years] I have led [function] at [Company] and [previous company]. My focus has been [one specific area, e.g. growth experimentation, design systems, supply chain optimization]. The work I am proudest of: [one concrete result, with a number].",{"br":true},{"br":true},"I am looking for a [role] at a [stage and type of company], ideally [remote / in city] and focused on [domain]. If you know of something or someone, I would love an intro. You can reach me at [email].",{"br":true},{"br":true},"Thank you to everyone who has already reached out."]},{"type":"h2","text":"Template 2: The story version"},{"type":"blockquote","runs":["A short update, and a small ask.",{"br":true},{"br":true},"Last Tuesday I was part of a layoff at [Company]. I am sad to leave the team and proud of what we built: [one sentence on a specific shipped outcome].",{"br":true},{"br":true},"I am taking a couple of weeks to rest, then opening up a search for [role] roles. The problems I most want to work on: [two short bullets].",{"br":true},{"br":true},"If any of that sounds like something you are building or know someone who is, I would welcome the introduction. [Email]."]},{"type":"h2","text":"Template 3: The pivot version"},{"type":"blockquote","runs":["I was laid off from [Company] last month, and I am using the moment to pivot.",{"br":true},{"br":true},"For the last [X years] I have done [previous function], most recently focused on [specific area]. The skills I want to bring forward: [two bullets]. The new direction I am exploring: [function or industry], because [one sentence of honest reasoning].",{"br":true},{"br":true},"Open to conversations with anyone in [target field], hiring or not. Coffee, a 15-minute call, anything that helps me learn faster is welcome. [Email]."]},{"type":"h2","text":"Small things that meaningfully raise the response rate"},{"type":"list","ordered":false,"items":[["Post on a Tuesday, Wednesday, or Thursday morning in your timezone. Engagement is noticeably higher than weekends or Mondays."],["Add the Open to Work green frame to your profile photo. It is the single biggest visibility lever LinkedIn gives you."],["Update your headline to what you do, not what you did. ''Senior Product Designer, fintech and consumer'' lands better than ''Senior Product Designer at [Defunct Company]''."],["Reply to every comment in the first 24 hours. The algorithm rewards conversation, not just likes."],["Pin the post to your profile for the first two weeks."]]},{"type":"h2","text":"What to do after you post"},{"type":"h3","text":"The first 48 hours"},{"type":"p","runs":["Expect a wave of well-wishes, a handful of real leads, and a few cold pitches from coaches and resume services. Reply warmly, log every concrete lead somewhere you will actually check (a tracker, not your inbox), and ignore the pitches."]},{"type":"h3","text":"The first two weeks"},{"type":"p","runs":["Send a short follow-up message to each person who offered a specific introduction or lead. Make it easy to help by including a one-paragraph blurb they can forward, plus your resume and the kind of roles you are targeting. The follow-up is where most of the actual value of the post gets unlocked."]},{"type":"p","runs":["Inside Offboard, every contact who reaches out, every lead, and every intro thread becomes part of your career memory, attached to the role and the company. You stop losing the intro that came in on day three because it was buried by day fourteen. The LinkedIn post is the spark. The follow-through is what turns it into a job."]}]'::jsonb, 5),
  ('best-job-application-trackers-2026', 'Best job application trackers in 2026: Huntr vs Teal vs Simplify vs spreadsheets', 'guides', 'An honest comparison of the four options most job seekers actually consider, what each does well, and how to pick the one you will actually keep up with.', '7 min read', '2026-06-04', 'Offboard', 'Team', null, ARRAY['rebuild-your-resume-after-a-layoff', 'how-ai-is-changing-the-job-search-in-2026']::text[], 'published', '[{"type":"p","runs":["Every job search starts the same way. A spreadsheet, maybe a Notion page, a few browser tabs, and the quiet promise that you will keep it updated. Two weeks in, the tracker is out of date, the recruiter threads are scattered across email and LinkedIn, and you cannot remember which version of your resume you sent where. The right tool fixes that. Here is an honest comparison of the four options most people actually consider in 2026."]},{"type":"h2","text":"What a good job tracker actually needs to do"},{"type":"list","ordered":false,"items":[["Capture an application from a job posting in one or two clicks, without retyping the company, title, and URL."],["Hold one source of truth per role: posting, resume version sent, cover letter, contacts, status, notes."],["Move applications through a real pipeline (saved, applied, screen, onsite, offer, closed) without ceremony."],["Surface what to do next today, not just a graveyard of stale rows."],["Stay private. Your search history is sensitive data."]]},{"type":"h2","text":"Huntr"},{"type":"p","runs":["Huntr was the first to nail the kanban-for-jobs format. The browser extension captures postings cleanly from LinkedIn, Greenhouse, Lever, and most ATS hosts. Free tier covers a light search; the paid tier adds resume tailoring and contact tracking."]},{"type":"h3","text":"Best for"},{"type":"p","runs":["People who think visually and want a clear kanban board. Strong if you are managing 30+ active applications and want to see the funnel at a glance."]},{"type":"h3","text":"Watch out for"},{"type":"p","runs":["Resume tailoring is generic AI rewriting, not grounded in your real career history. Easy to produce something that reads fluently but does not actually match the role."]},{"type":"h2","text":"Teal"},{"type":"p","runs":["Teal leans heavier on resume building. The tracker is solid (kanban or list view), and the resume tool has good keyword analysis against job descriptions. Free tier is generous; paid tier (Teal+) unlocks unlimited AI features."]},{"type":"h3","text":"Best for"},{"type":"p","runs":["People who want resume tooling and tracking in one place and are willing to manage versions manually. Good fit if you are early-career or pivoting and need to iterate on resume framing a lot."]},{"type":"h3","text":"Watch out for"},{"type":"p","runs":["Keyword matching is not the same as ATS optimization. A resume that scores 90% on Teal''s match meter can still get filtered by an actual ATS because of formatting or section headers."]},{"type":"h2","text":"Simplify"},{"type":"p","runs":["Simplify''s pitch is autofill. Their extension fills out application forms across most major ATS platforms, which genuinely saves time on volume applications. They also added a tracker and a job board."]},{"type":"h3","text":"Best for"},{"type":"p","runs":["High-volume applicants, especially early-career and new grads applying to dozens of roles a week. The autofill is the real product."]},{"type":"h3","text":"Watch out for"},{"type":"p","runs":["Autofill encourages spray-and-pray. The applications that actually convert in 2026 are the ones tailored to the role, not the ones submitted fastest. The tracker piece is lightweight compared to Huntr or Teal."]},{"type":"h2","text":"A spreadsheet"},{"type":"p","runs":["Still the most popular tracker by far, and there is no shame in it. A clean Google Sheet with columns for company, role, source, date applied, contact, status, and next step beats every fancy tool that you do not actually update."]},{"type":"h3","text":"Best for"},{"type":"p","runs":["Searches under about 20 active applications, or anyone who already has a system they trust. Free, private, no learning curve."]},{"type":"h3","text":"Watch out for"},{"type":"p","runs":["Manual everything. No reminders, no resume versioning, no contact threading. The spreadsheet is only as good as your discipline to update it, and most searches lose that discipline by week three."]},{"type":"h2","text":"Where Offboard fits"},{"type":"p","runs":["Offboard''s tracker is built into the same workspace as your resume, cover letters, interview prep, and financial runway. The difference is memory: when LUMO helps you tailor a resume for a role, it already knows which version you sent to the last similar role, what notes you took after the screen, and which contacts at the company you have talked to. The tracker is one view on top of a connected career memory, not a standalone board you have to sync manually with the rest of your search."]},{"type":"callout","runs":["High volume, mostly autofill: Simplify. Visual board, contact tracking: Huntr. Resume-first iteration: Teal. Under 20 applications and you trust your habits: a spreadsheet. Anything post-layoff where you need resumes, interviews, runway, and tracking to share context: Offboard."],"title":"How to choose"},{"type":"p","runs":["The tool matters less than the habit. Whichever you pick, set a daily 15-minute checkpoint to log new applications, move stale ones, and decide one concrete next action. That habit is what separates searches that compound from searches that fizzle."]}]'::jsonb, 6),
  ('how-ai-is-changing-the-job-search-in-2026', 'How AI Is Changing the Job Search in 2026', 'ai-and-technology', 'AI is changing the job search in 2026 by speeding up hiring, filtering candidates earlier, and reshaping resume screening. Here''s what job seekers need to know.', '10 min read', '2026-03-17', 'Offboard', 'Team', null, ARRAY['what-is-an-ai-agent', '7-levels-ai-agent-capability']::text[], 'published', '[{"type":"p","runs":["If the 2025 job market felt exhausting, 2026 feels even stranger."]},{"type":"p","runs":["You are not just competing against other candidates anymore. You are also trying to get past automated filters, AI ranking systems, resume parsers, job-matching engines, and sometimes interview tools before a real person ever looks at your application. AI is now embedded across the hiring process, especially in screening, matching, and early candidate evaluation. It is making hiring faster and more scalable, but also more opaque and harder for job seekers to read."]},{"type":"p","runs":["That matters because the rules of the game have changed."]},{"type":"p","runs":["The big story is not that AI has replaced recruiters. It has not. The real shift is that AI is increasingly deciding who gets seen, who gets filtered out, and how a candidate gets interpreted before a human steps in. The strongest evidence still favors hybrid hiring systems where AI handles speed and logistics while humans handle context, judgment, and relationship-building."]},{"type":"p","runs":["So if you are job searching right now, here is the truth: AI can absolutely help you, but AI can also quietly work against you."]},{"type":"divider"},{"type":"h2","text":"AI is making hiring faster, but not necessarily better"},{"type":"p","runs":["One of the clearest findings in the research is that AI is improving efficiency in recruiting. Studies and reviews consistently show that AI tools cut time-to-hire and reduce recruiter workload by automating resume parsing, ranking, and initial assessments. Some surveys and case studies report 40 to 70 percent reductions in hiring time, along with lower cost-per-hire."]},{"type":"p","runs":["That sounds great on paper, and for employers it often is."]},{"type":"p","runs":["For job seekers, though, faster hiring does not always feel better. A quicker process can still be confusing, impersonal, and hard to interpret. It can mean you get rejected faster, screened out earlier, and never learn why. AI improves speed. It does not automatically improve fairness, warmth, or judgment."]},{"type":"h2","text":"AI is increasingly deciding who gets seen at all"},{"type":"p","runs":["This is the part more job seekers need to understand."]},{"type":"p","runs":["According to the research, AI screening commonly removes 50 to 75 percent of applicants automatically based on learned patterns from prior hiring decisions. At the same time, newer semantic matching systems can sometimes surface nontraditional candidates better than simple keyword filters can. The catch is that these systems can also bake in historical preferences unless they are carefully audited."]},{"type":"p","runs":["That means your challenge is no longer just impressing the hiring manager. It is surviving the machine before the hiring manager ever knows you exist."]},{"type":"p","runs":["This is especially important for career changers, people coming off layoffs, self-taught candidates, and anyone with a resume that does not fit a neat template. AI can widen the door for you. It can also quietly narrow it."]},{"type":"h2","text":"Resume writing is now an AI-versus-AI problem"},{"type":"p","runs":["This is one of the most important and weirdest shifts in modern hiring."]},{"type":"p","runs":["A 2025 experiment found that large language models used as hiring screeners strongly preferred resumes written by the same model over equally qualified human-written resumes or outputs from rival models. The shortlisting advantage ranged from 23 to 60 percent. The paper describes this as a kind of algorithmic accent. Some resumes are simply more legible to certain AI systems, regardless of whether the underlying candidate is actually better."]},{"type":"p","runs":["That is a big deal."]},{"type":"p","runs":["It means job seekers are not just being judged on experience anymore. They may also be helped or hurt by how closely their resume matches the style patterns favored by the AI sitting on the other side of the table."]},{"type":"p","runs":["So yes, use AI to improve your resume. But do not hand over your voice completely. The goal is not to sound like a robot that flatters another robot. The goal is to be clear, specific, and credible."]},{"type":"h2","text":"Job matching is getting smarter and more personalized"},{"type":"p","runs":["AI is not only being used to reject people. It is also being used to recommend jobs, sort candidates into better-fit roles, and personalize matching based on skills, geography, behavior, and preferences. Research in high-volume and campus recruiting environments shows 30 percent or greater gains in match quality, plus improvements in retention, when AI is used to support matching rather than fully automate hiring decisions."]},{"type":"p","runs":["This is one of the more promising parts of the shift."]},{"type":"p","runs":["Done well, AI can help candidates waste less time on bad-fit roles and discover better opportunities faster. Done poorly, it can trap people inside recommendation loops that keep feeding them variations of what the system already thinks they are."]},{"type":"p","runs":["That is one reason job seekers should not outsource their whole search to job recommendations alone. Discovery still matters. Exploration still matters. Human networking still matters."]},{"type":"h2","text":"The candidate experience is getting smoother, but less human"},{"type":"p","runs":["AI-powered chatbots, scheduling tools, and status portals are making hiring more responsive and more structured. Candidates often get faster updates, easier scheduling, and less dead silence. That part is real."]},{"type":"p","runs":["But the same research shows a downside: many candidates report lower perceived personalization and fairness in AI-heavy processes. They worry about opaque criteria, limited ability to explain unusual circumstances, and the sense that their story is being flattened into data points. Best outcomes tend to come from hybrid models where AI handles logistics and humans handle relationship-building."]},{"type":"p","runs":["That distinction matters."]},{"type":"p","runs":["A process can feel polished and still feel cold. It can feel efficient and still feel unfair."]},{"type":"h2","text":"AI may help reduce bias, but only with real oversight"},{"type":"p","runs":["There is a tempting story that AI will make hiring more objective. The research does not support that simple version."]},{"type":"p","runs":["What it does support is more conditional. AI can outperform humans on some diversity metrics when fairness constraints and blinding are designed into the system. But bias can re-emerge quickly when the training data reflects past discrimination or when systems are not monitored over time. The consensus from the research is blunt: AI can improve equity or worsen it depending on design and governance."]},{"type":"p","runs":["That means AI is not neutral. It is an amplifier."]},{"type":"p","runs":["If the process is built well, it may reduce some human bias. If the process is built badly, it can scale bias faster and hide it behind technical language."]},{"type":"h2","text":"Recruiters still do not fully trust AI, and that matters"},{"type":"p","runs":["One of the more useful findings in the research is that recruiters themselves are often skeptical of algorithmic recommendations. In a large resume-screening experiment with 694 professionals, recruiters trusted human recommendations more than AI recommendations and showed algorithm aversion in subjective decisions. Inconsistent AI suggestions could even push them toward worse candidates."]},{"type":"p","runs":["That matters because it explains why full automation has not taken over hiring, despite the hype."]},{"type":"p","runs":["Companies still need humans in the loop, not just for ethics, but because trust and legitimacy matter in hiring. People want someone to be accountable when the stakes are high."]},{"type":"h2","text":"AI interview prep is rising fast, but AI interviewers are still a gray area"},{"type":"p","runs":["There is a big difference between AI helping you prepare for an interview and AI judging you in one."]},{"type":"p","runs":["The research shows that AI interviewers and AI-driven video tools are spreading, and controlled studies suggest that more human-like virtual interviewers can create better user experiences in training contexts. But when AI moves from coach to evaluator, the concerns rise quickly, especially around bias, candidate commitment, and experience. The research describes this as active experimentation, not settled best practice."]},{"type":"p","runs":["That is the right way to think about it in 2026."]},{"type":"p","runs":["Using AI to practice is smart. Letting AI over-interpret speech patterns, facial cues, or nonverbal behavior in real interviews is much more questionable."]},{"type":"h2","text":"The future of hiring is not AI-only. It is hybrid."},{"type":"p","runs":["This is probably the clearest conclusion in the whole research set."]},{"type":"p","runs":["Systematic reviews and hybrid-model studies point to the same pattern: AI is good at scale, speed, and consistency. Humans are better at context, soft skills, and moral judgment. Hybrid hiring pipelines reduce time-to-hire by roughly 25 to 40 percent, improve quality-of-hire and diversity, and deliver higher candidate satisfaction than either AI-only or human-only approaches."]},{"type":"p","runs":["So the debate is no longer AI versus recruiters."]},{"type":"p","runs":["The real question is who should do what, and who should be accountable when decisions affect someone''s career."]},{"type":"h2","text":"What job seekers should do differently in 2026"},{"type":"p","runs":["If you are searching for work right now, here is the practical takeaway."]},{"type":"p","runs":["Use AI, but do not disappear into it."]},{"type":"p","runs":["Use it to sharpen your resume, tailor your materials, prep for interviews, organize your search, and speed up repetitive work. But do not rely on generic AI output and call it strategy. The best candidates in 2026 are not the ones who generate the most content. They are the ones who use AI to become more clear, more prepared, and more specific - without losing the human signal that makes them memorable."]},{"type":"p","runs":["That means:"]},{"type":"h3","text":"1. Optimize for both humans and machines"},{"type":"p","runs":["Your resume needs structure, clarity, and role relevance. It should be readable by AI screening systems and still persuasive to a recruiter once it gets through."]},{"type":"h3","text":"2. Be more specific, not more verbose"},{"type":"p","runs":["Generic AI writing is everywhere now. Specific achievements, proof of work, and concrete outcomes stand out more."]},{"type":"h3","text":"3. Do not rely only on online applications"},{"type":"p","runs":["If AI is filtering the top of the funnel, direct outreach, referrals, and real networking become even more valuable."]},{"type":"h3","text":"4. Use AI for prep, not identity"},{"type":"p","runs":["AI can help you think better and move faster. It should not erase your voice or flatten your story."]},{"type":"h3","text":"5. Expect opacity, then build around it"},{"type":"p","runs":["You will not always know why you got filtered out. Build a search process that does not depend on one channel, one platform, or one system saying yes."]},{"type":"divider"},{"type":"h2","text":"Final thought"},{"type":"p","runs":["AI is changing the job search in 2026 in very real ways. It is making hiring faster, more automated, and more data-driven. It is also making the process more opaque, more selective at the top of the funnel, and more dependent on systems candidates cannot see. The strongest evidence does not point to a world where recruiters disappear. It points to a world where AI has growing power over access, while humans still matter most for judgment, trust, and accountability."]},{"type":"p","runs":["For job seekers, the goal is not to fear AI or blindly trust it."]},{"type":"p","runs":[{"b":["It is to understand the new game faster than everyone else."]}]}]'::jsonb, 7),
  ('what-is-an-ai-agent', 'What Is an AI Agent? A Simple Guide to the Different Types of AI Agents', 'ai-and-technology', 'A clear, jargon-free guide to what AI agents actually are, how they differ from chatbots and automation, and the different types you should know about.', '10 min read', '2026-03-16', 'Offboard', 'Team', null, ARRAY['7-levels-ai-agent-capability', 'how-ai-is-changing-the-job-search-in-2026']::text[], 'published', '[{"type":"p","runs":["If you have spent any time around AI lately, you have probably heard the word"," ",{"i":["agent"]}," thrown around constantly. AI agents are suddenly everywhere. One company says their agent can research and write reports. Another says their agents can book meetings, update CRM records, and send follow-ups. Meanwhile, plenty of products that are really just chatbots or automation tools are also being marketed as agents."]},{"type":"p","runs":["So what actually counts as an AI agent? And what are the different types of AI agents people are talking about?"]},{"type":"h2","text":"What is an AI agent?"},{"type":"p","runs":["An AI agent is a software system that can understand a goal, perceive context, reason about what to do, and take actions to move toward that goal. That is what separates an agent from a basic chatbot."]},{"type":"p","runs":["A chatbot mostly responds to prompts. An agent can take action."]},{"type":"p","runs":["The strongest current definitions all point in roughly the same direction:"]},{"type":"list","ordered":false,"items":[[{"b":["Anthropic"]}," distinguishes between workflows, where code determines the path, and agents, where the model dynamically directs its own process and tool use."],[{"b":["Google Cloud"]}," defines AI agents as systems that pursue goals on behalf of users and show reasoning, planning, memory, and some autonomy."],[{"b":["Microsoft"]}," describes an agent as a system that perceives its environment through inputs and takes actions to achieve a defined objective."],[{"b":["IBM"]}," defines AI agents as systems capable of autonomously performing tasks on behalf of a user or another system."]]},{"type":"p","runs":["Put simply:"," ",{"b":["An AI agent is not just something that talks. It is something that can decide and do."]}]},{"type":"h2","text":"AI agent vs chatbot vs automation"},{"type":"p","runs":["This is where a lot of confusion comes from."]},{"type":"h3","text":"Chatbot"},{"type":"p","runs":["A chatbot is mainly designed to respond to user input in conversation. Examples:"]},{"type":"list","ordered":false,"items":[["Answering questions"],["Summarizing text"],["Drafting messages"],["Explaining concepts"]]},{"type":"p","runs":["A chatbot may feel smart, but it usually stops at the response."]},{"type":"h3","text":"Automation"},{"type":"p","runs":["Automation follows predefined rules. Examples:"]},{"type":"list","ordered":false,"items":[["If a form is submitted, send an email"],["If a lead changes stage, assign a task"],["If a meeting is booked, create a calendar event"]]},{"type":"p","runs":["Automation is powerful, but it is not intelligent in the same way. It typically does not reason through a situation in real time."]},{"type":"h3","text":"AI agent"},{"type":"p","runs":["An AI agent combines intelligence with action. Examples:"]},{"type":"list","ordered":false,"items":[["Research a company, summarize findings, and draft a tailored outreach email"],["Read an incoming email, decide whether it is urgent, and route it appropriately"],["Review a job posting, compare it to your background, and recommend whether it is worth pursuing"]]},{"type":"p","runs":["The important distinction is that an agent is working toward an objective, not just firing a rule or replying with text."]},{"type":"h2","text":"How do AI agents work?"},{"type":"p","runs":["Most modern AI agents follow some version of a loop like this:"]},{"type":"list","ordered":true,"items":[["Observe the current situation or inputs"],["Reason about what matters"],["Plan the next step or sequence of steps"],["Act using available tools"],["Review the result and adjust if needed"]]},{"type":"p","runs":["Microsoft describes AI agents as following a perception-reasoning-action loop, and Google highlights reasoning, acting, observing, and planning as core features. More advanced systems also add memory, collaboration, and self-refinement."]},{"type":"p","runs":["In plain English: an agent looks at the situation, decides what to do, does it, sees what happened, and keeps going if needed."]},{"type":"h2","text":"The classic 5 types of AI agents"},{"type":"p","runs":["If you search for “different types of AI agents,” you will often find the classic AI taxonomy. IBM summarizes five main types:"]},{"type":"h3","text":"1. Simple reflex agents"},{"type":"p","runs":["These are the most basic. They respond directly to current conditions using fixed rules. Examples:"]},{"type":"list","ordered":false,"items":[["A thermostat turning heat on or off based on temperature"],["A basic spam filter blocking messages based on predefined patterns"]]},{"type":"p","runs":["These systems are useful in predictable environments, but they do not remember the past or plan for the future."]},{"type":"h3","text":"2. Model-based reflex agents"},{"type":"p","runs":["These agents still use rules, but they also maintain an internal model of the world. That means they can track state, not just immediate input. Examples:"]},{"type":"list","ordered":false,"items":[["A robot vacuum that remembers which areas it has already cleaned"],["A navigation system that tracks known obstacles and room layout"]]},{"type":"p","runs":["Best for: stateful environments where memory matters."]},{"type":"h3","text":"3. Goal-based agents"},{"type":"p","runs":["These agents evaluate actions based on whether they help achieve a goal. Examples:"]},{"type":"list","ordered":false,"items":[["A route planner trying to find the best way to get from point A to point B"],["A sales assistant agent trying to move a lead toward a booked demo"]]},{"type":"p","runs":["Goal-based agents are more flexible because they are not only reacting. They are choosing actions in service of an objective."]},{"type":"h3","text":"4. Utility-based agents"},{"type":"p","runs":["These agents do not just ask, “Does this help achieve the goal?” They ask, “Which option is best among competing tradeoffs?” Examples:"]},{"type":"list","ordered":false,"items":[["A delivery system balancing speed, fuel cost, and reliability"],["An AI assistant deciding whether to interrupt you now or wait until later based on urgency and context"]]},{"type":"p","runs":["Best for: optimization under competing priorities."]},{"type":"h3","text":"5. Learning agents"},{"type":"p","runs":["These agents improve over time based on experience and feedback. Examples:"]},{"type":"list","ordered":false,"items":[["Recommendation systems that improve as users interact with them"],["Fraud detection systems that get better as they see more examples"],["Assistants that learn which actions are most useful in a given workflow"]]},{"type":"p","runs":["A learning agent is not stuck with the same rules forever. It adapts."]},{"type":"h2","text":"The modern types people actually mean"},{"type":"p","runs":["The classic taxonomy is still useful, but in practice most people talking about AI agents today mean a more modern set of categories. Here is a simpler practical breakdown."]},{"type":"h3","text":"1. Prompt-and-response agents"},{"type":"p","runs":["The lightest version. They take in a prompt and produce a useful result, sometimes with some tool use, but they are still fairly session-based. Examples:"]},{"type":"list","ordered":false,"items":[["A writing assistant"],["A meeting-note summarizer"],["A customer-support responder"]]},{"type":"h3","text":"2. Workflow agents"},{"type":"p","runs":["These operate within predefined paths. Anthropic makes an important distinction here: workflows are agentic systems where the LLM and tools are orchestrated through predefined code paths, while true agents dynamically direct their own process. Examples:"]},{"type":"list","ordered":false,"items":[["A support flow that always classifies, drafts, escalates, and logs in the same order"],["A hiring flow that always reviews a resume, scores fit, and drafts follow-up questions"]]},{"type":"p","runs":["Workflow agents can be very effective and often more predictable than open-ended agents."]},{"type":"h3","text":"3. Tool-using agents"},{"type":"p","runs":["These are the systems most people picture when they hear “AI agent.” They can call tools like web search, APIs, calendars, CRMs, file systems, and internal databases. Examples:"]},{"type":"list","ordered":false,"items":[["An agent that researches prospects and updates a CRM"],["An agent that reads a contract and flags unusual clauses"],["An agent that analyzes job descriptions and drafts tailored outreach"]]},{"type":"h3","text":"4. Multi-agent systems"},{"type":"p","runs":["These systems use multiple agents that each specialize in a different part of a task. One agent might research. Another might write. Another might validate findings. Examples:"]},{"type":"list","ordered":false,"items":[["A design tool where multiple agents build different parts of a prototype"],["A research system where several agents gather evidence in parallel and one synthesizes the answer"]]},{"type":"h3","text":"5. Persistent agents"},{"type":"p","runs":["These agents work over time, not just in one session. They remember the goal, retain state, and carry work forward across days or weeks. Examples:"]},{"type":"list","ordered":false,"items":[["An agent managing an ongoing job search"],["An agent helping a founder prepare for fundraising over several weeks"],["An agent guiding a customer-success process from onboarding through renewal"]]},{"type":"h3","text":"6. Adaptive agents"},{"type":"p","runs":["These agents do not just continue over time. They also change strategy based on what is happening:"]},{"type":"list","ordered":false,"items":[["An agent that notices outreach is not getting replies and shifts the playbook"],["An agent that sees interview traction but no offers and pivots toward interview coaching"],["An agent that reprioritizes based on urgency, feedback, or changing constraints"]]},{"type":"p","runs":["This is where AI starts to feel more strategic."]},{"type":"h2","text":"What makes an AI agent good?"},{"type":"p","runs":["Not every AI agent is good just because it can call tools. The most useful agents usually have a few things in common:"]},{"type":"list","ordered":false,"items":[[{"b":["Clear goals"]}," - If the objective is vague, the output often gets vague too."],[{"b":["The right tools"]}," - An agent is only as useful as the systems it can access."],[{"b":["Strong context"]}," - Agents need the right information at the right time."],[{"b":["Memory or state"]}," - Many real-world tasks require continuity."],[{"b":["Feedback loops"]}," - The agent should be able to learn what worked."],[{"b":["Guardrails"]}," - Human oversight, permissions, and limits matter a lot."]]},{"type":"p","runs":["Anthropic explicitly recommends starting with the simplest possible solution and only increasing complexity when needed, because more agentic systems often trade predictability, latency, and cost for flexibility."]},{"type":"h2","text":"When should you use an AI agent?"},{"type":"p","runs":["Use an AI agent when the job:"]},{"type":"list","ordered":false,"items":[["Has multiple steps"],["Benefits from reasoning and tool use"],["Changes based on context"],["Requires flexibility rather than rigid rules"],["Has a clear enough objective to guide decisions"]]},{"type":"p","runs":["Examples: sales prospecting, customer support triage, recruiting coordination, financial analysis, research and reporting, job search management."]},{"type":"p","runs":["Do not assume you need an agent when a simple prompt, retrieval system, or workflow automation would do the job more reliably and cheaply."]},{"type":"h2","text":"Why AI agents matter"},{"type":"p","runs":["AI agents matter because they shift software from passive tools to active systems. Instead of just helping you think, they can help you move."]},{"type":"p","runs":["That does not mean every agent should be fully autonomous. But it does mean software is starting to move from:"]},{"type":"list","ordered":false,"items":[["Answering"],["To assisting"],["To acting"],["To adapting"]]},{"type":"p","runs":["That is a major shift."]},{"type":"h2","text":"Final takeaway"},{"type":"p","runs":["If you remember one thing, make it this:"]},{"type":"p","runs":[{"b":["A chatbot talks. Automation follows rules. An AI agent works toward a goal."]}]},{"type":"p","runs":["And as AI keeps improving, the most important differences between agents will come down to a few key questions:"]},{"type":"list","ordered":false,"items":[["Can it take action?"],["Can it use tools?"],["Can it remember context?"],["Can it adapt?"],["Can it coordinate multiple steps or agents?"],["Can it improve over time?"]]},{"type":"p","runs":["Those are the questions that separate a flashy demo from a genuinely useful system. At Offboard, we think that distinction matters a lot - especially in areas like job search, where people do not just need answers. They need systems that can help them manage a mission over time."]}]'::jsonb, 8),
  ('7-levels-ai-agent-capability', 'The 7 Levels of AI Agent Capability: Where AI Is Going Next', 'ai-and-technology', 'A practical framework for understanding AI agent maturity, from basic intelligence to collective learning, and why it matters for your job search.', '9 min read', '2026-03-16', 'Offboard', 'Team', null, ARRAY['what-is-an-ai-agent', 'how-ai-is-changing-the-job-search-in-2026']::text[], 'published', '[{"type":"p","runs":["Artificial intelligence is changing so fast that it is easy to get distracted by demos."]},{"type":"p","runs":["One week, everyone is talking about a chatbot that can write code. The next week, it is a swarm of agents moving around a canvas. Then it is a voice assistant booking meetings, summarizing calls, and sending follow-ups."]},{"type":"p","runs":["The surface keeps changing."]},{"type":"p","runs":["But underneath all of it, there is a much more important question:"]},{"type":"p","runs":[{"b":["What are the actual levels of AI capability, and where is all of this heading?"]}]},{"type":"p","runs":["That question matters for founders, product teams, investors, and everyday users. If you do not have a framework, it becomes very easy to confuse flashy interfaces with meaningful leaps in intelligence."]},{"type":"p","runs":["At Offboard, we spend a lot of time thinking about this because job search is one of the clearest examples of where AI should go next. A job search is not a single task. It is a messy, emotional, multi-week mission full of changing conditions, missed signals, deadlines, self-doubt, and constant reprioritization."]},{"type":"p","runs":["That makes it a great lens for thinking about the future of AI agents."]},{"type":"p","runs":["Here is the framework I keep coming back to."]},{"type":"h2","text":"Level 1: Intelligence"},{"type":"p","runs":["This is the foundation."]},{"type":"p","runs":["Large language models brought us a new kind of software primitive: systems that can understand language, reason through problems, generate content, summarize, explain, and answer questions."]},{"type":"p","runs":["This first level is about knowledge and reasoning."]},{"type":"p","runs":["An AI at this level can:"]},{"type":"list","ordered":false,"items":[["answer a question"],["draft a message"],["summarize a document"],["brainstorm ideas"],["explain a concept"],["generate code or content"]]},{"type":"p","runs":["This is the level most people first encountered with ChatGPT and similar products."]},{"type":"p","runs":["It was a huge breakthrough, but it is still mostly passive. The model waits for the user to ask for something."]},{"type":"p","runs":[{"b":["In simple terms: it knows."]}]},{"type":"h2","text":"Level 2: Agency"},{"type":"p","runs":["The second level is where AI begins to ",{"i":["do"]}," things, not just say things."]},{"type":"p","runs":["An agent combines intelligence with tool use. It can access software, browse the web, call APIs, update records, send drafts, read files, schedule actions, or manipulate a user interface."]},{"type":"p","runs":["This is where AI starts to feel useful in a more concrete way."]},{"type":"p","runs":["An agent at this level can:"]},{"type":"list","ordered":false,"items":[["research across multiple sources"],["update a CRM"],["draft and send outreach"],["modify a calendar or task list"],["read and analyze uploaded files"],["take action inside software tools"]]},{"type":"p","runs":["This is the category most people mean when they say “AI agent” today."]},{"type":"p","runs":["The common mental model is:"]},{"type":"blockquote","runs":["LLM + tools = agent"]},{"type":"p","runs":["That is a decent shorthand."]},{"type":"p","runs":["But this level is still often episodic. The agent handles a task or a session, then stops."]},{"type":"p","runs":[{"b":["In simple terms: it acts."]}]},{"type":"h2","text":"Level 3: Persistence"},{"type":"p","runs":["This is where things start to get much more interesting."]},{"type":"p","runs":["A persistent agent does not just complete a task and disappear. It stays connected to the problem over time."]},{"type":"p","runs":["It remembers the goal. It retains state. It can carry context across sessions. It does not need to be fully re-briefed every time."]},{"type":"p","runs":["This is the difference between:"]},{"type":"list","ordered":false,"items":[["“Help me draft this message”"],["“Help me keep making progress on this mission over the next six weeks”"]]},{"type":"p","runs":["A persistent agent can:"]},{"type":"list","ordered":false,"items":[["track progress over time"],["remember what matters"],["carry unfinished work forward"],["maintain continuity across sessions"],["stay oriented around an outcome rather than a single prompt"]]},{"type":"p","runs":["This is a major shift."]},{"type":"p","runs":["Most AI today is still task-based. Persistence is where AI starts to become longitudinal."]},{"type":"p","runs":[{"b":["In simple terms: it stays with the problem."]}]},{"type":"h2","text":"Level 4: Adaptation"},{"type":"p","runs":["Persistence alone is not enough."]},{"type":"p","runs":["A system can remember context and still be dumb about what to do next."]},{"type":"p","runs":["The next level is adaptation: the ability to change strategy as conditions change."]},{"type":"p","runs":["An adaptive agent does not just keep going. It learns from what is happening and adjusts."]},{"type":"p","runs":["That means it can notice things like:"]},{"type":"list","ordered":false,"items":[["the current strategy is not working"],["a deadline is becoming urgent"],["the user is losing momentum"],["the environment has changed"],["a better path has opened up"],["the goal is the same, but the plan should change"]]},{"type":"p","runs":["This is the level where AI begins to feel less like automation and more like judgment."]},{"type":"p","runs":["A lot of people describe the future of AI as “more autonomous.” That is part of it. But autonomy without adaptation is overrated. What matters is not that the system keeps moving. It is that it knows how to change course intelligently."]},{"type":"p","runs":[{"b":["In simple terms: it adjusts."]}]},{"type":"h2","text":"Level 5: Orchestration"},{"type":"p","runs":["Once you have persistence and adaptation, the next leap is orchestration."]},{"type":"p","runs":["This is where multiple workflows, tools, or specialized agents work together under one higher-level objective."]},{"type":"p","runs":["We are already seeing early versions of this. Some products let you deploy multiple agents in parallel. Others split work across research, planning, writing, design, or code generation. In some cases, you can literally watch multiple agent cursors moving around a canvas or see several research threads being executed at once."]},{"type":"p","runs":["That is not just a gimmick."]},{"type":"p","runs":["It points to a future where AI is not one general helper, but a coordinated system of specialists."]},{"type":"p","runs":["An orchestrated system can:"]},{"type":"list","ordered":false,"items":[["divide work across specialized agents"],["run parallel research or execution paths"],["combine findings into one recommendation"],["coordinate multiple moving parts under one mission"],["prioritize which sub-problem matters most right now"]]},{"type":"p","runs":[{"b":["In simple terms: it coordinates."]}]},{"type":"h2","text":"Level 6: Anticipation"},{"type":"p","runs":["This is where the framework starts to move from useful to truly strategic."]},{"type":"p","runs":["An anticipatory system does not just respond to what has happened. It models what is likely to happen next and helps shape the path before problems fully emerge."]},{"type":"p","runs":["This is the beginning of something closer to a world model."]},{"type":"p","runs":["An anticipatory agent can:"]},{"type":"list","ordered":false,"items":[["infer which path has a higher chance of success"],["detect likely bottlenecks before they become obvious"],["simulate tradeoffs between different approaches"],["predict which actions matter most right now"],["recommend pivots before the user loses too much time"]]},{"type":"p","runs":["This is a very different experience from basic AI assistance."]},{"type":"p","runs":["Instead of saying, “Here is the answer to your question,” it starts saying, “Given everything I know about your goal, your environment, and the outcomes so far, I think path B now has a better expected return than path A.”"]},{"type":"p","runs":["That is a serious jump."]},{"type":"p","runs":[{"b":["In simple terms: it chooses ahead."]}]},{"type":"h2","text":"Level 7: Collective Learning"},{"type":"p","runs":["The final level in this framework is collective learning."]},{"type":"p","runs":["This is where the system improves not just from one user''s history, but from patterns across many users, workflows, and outcomes."]},{"type":"p","runs":["At this level, the AI is no longer just helping a person in the moment. It is building a domain-specific intelligence layer."]},{"type":"p","runs":["A system with collective learning can:"]},{"type":"list","ordered":false,"items":[["learn which behaviors lead to the best outcomes"],["identify patterns across many users and cases"],["improve recommendations based on real-world feedback"],["create better playbooks over time"],["compound value as usage grows"]]},{"type":"p","runs":["This is where real defensibility starts to appear."]},{"type":"p","runs":["It is also where the gap between generic AI wrappers and category-defining products gets much bigger."]},{"type":"p","runs":[{"b":["In simple terms: it compounds."]}]},{"type":"h2","text":"Why this framework matters"},{"type":"p","runs":["A lot of AI product conversations get stuck because people mix up these levels."]},{"type":"p","runs":["A company will say they have an “agent,” but what they really have is a smart content generator with a few triggers."]},{"type":"p","runs":["Another company will show a multi-agent demo, but it still lacks persistence. It looks impressive in the moment, yet has no real continuity."]},{"type":"p","runs":["Another tool may remember context, but it does not adapt when the situation changes."]},{"type":"p","runs":["These are not all the same thing."]},{"type":"p","runs":["That is why having a framework matters."]},{"type":"p","runs":["It helps you ask better questions:"]},{"type":"list","ordered":false,"items":[["Is this system just intelligent, or is it agentic?"],["Is it agentic, or is it persistent?"],["Is it persistent, or is it adaptive?"],["Is it adaptive, or can it orchestrate?"],["Can it anticipate, or does it only react?"],["Does it learn across outcomes, or does it reset every time?"]]},{"type":"p","runs":["That is how you separate novelty from actual capability."]},{"type":"h2","text":"The Roz test"},{"type":"p","runs":["One of my favorite analogies for this came from ",{"i":["The Wild Robot"]},"."]},{"type":"p","runs":["Roz is interesting not because she can perform tasks. She is interesting because she locks onto a mission, adapts to a changing world, and keeps working toward the outcome through hundreds of sub-tasks."]},{"type":"p","runs":["She does not just need a new prompt every few minutes."]},{"type":"p","runs":["She stays oriented around the mission."]},{"type":"p","runs":["That is a useful benchmark for where AI is heading."]},{"type":"p","runs":["The best AI systems of the future will not just be smart tools. They will feel more like mission-aware systems that can stay grounded in an objective, adjust to changing conditions, and keep making progress over time."]},{"type":"p","runs":["That does not mean humans disappear from the loop. In many cases, quite the opposite. As AI becomes more powerful, trust, control, and judgment will matter even more. The systems that win will likely be the ones that feel collaborative, transparent, and aligned, not just hyper-automated."]},{"type":"h2","text":"What this means for the future of job search"},{"type":"p","runs":["Job search is one of the clearest areas where this evolution matters."]},{"type":"p","runs":["The old process of applying cold through job boards is already under pressure. Recruiters are overloaded. Job seekers are overwhelmed. More of the process is fragmenting across referrals, communities, personal brands, direct outreach, AI-assisted applications, and internal talent networks."]},{"type":"p","runs":["In that world, a basic assistant is not enough."]},{"type":"p","runs":["Job seekers do not just need a chatbot that can rewrite a resume. They need help navigating a mission."]},{"type":"p","runs":["That mission includes:"]},{"type":"list","ordered":false,"items":[["choosing which roles are actually worth pursuing"],["deciding where to spend limited time and energy"],["adjusting strategy based on traction or lack of traction"],["preparing for interviews"],["managing emotional momentum"],["balancing ideal roles against financial urgency"],["keeping all of the moving parts organized across weeks or months"]]},{"type":"p","runs":["That is why we believe the future is not just AI assistance. It is adaptive, persistent AI that can help users manage a real-life transition."]},{"type":"h2","text":"Final thought"},{"type":"p","runs":["AI is not evolving in one straight line."]},{"type":"p","runs":["It is expanding across several dimensions at once: intelligence, action, persistence, adaptation, coordination, anticipation, and learning."]},{"type":"p","runs":["But if I had to simplify the path, I would say it like this:"]},{"type":"list","ordered":false,"items":[[{"b":["Intelligence"]}," means AI knows."],[{"b":["Agency"]}," means AI acts."],[{"b":["Persistence"]}," means AI stays with the problem."],[{"b":["Adaptation"]}," means AI changes strategy."],[{"b":["Orchestration"]}," means AI coordinates many moving parts."],[{"b":["Anticipation"]}," means AI sees around corners."],[{"b":["Collective learning"]}," means AI gets better across outcomes."]]},{"type":"p","runs":["That is the ladder."]},{"type":"p","runs":["And the products that matter most in the next few years will probably not be the ones with the flashiest demo. They will be the ones that move meaningfully up that ladder in ways that solve real human problems."]},{"type":"p","runs":["At Offboard, that is the direction we are building toward."]},{"type":"p","runs":["Not just AI that answers."]},{"type":"p","runs":[{"b":["AI that stays with the mission."]}]},{"type":"p","runs":[{"i":["If you''re navigating a layoff or job search and want an AI system built for the full journey, not just isolated tasks, Offboard is building exactly that."]}]}]'::jsonb, 9),
  ('will-employers-know-cover-letter-is-ai', 'Will employers know your cover letter is AI? What detection actually catches', 'ai-and-technology', 'Most employers do not run cover letters through AI detectors, and the detectors that exist are unreliable. The real risk is sounding generic. Here is how to use AI without sabotaging your shot.', '6 min read', '2026-06-04', 'Offboard', 'Team', null, ARRAY['how-ai-is-changing-the-job-search-in-2026', 'rebuild-your-resume-after-a-layoff']::text[], 'published', '[{"type":"p","runs":["Short answer: most employers do not run cover letters through AI detectors, the detectors that exist are unreliable, and the real risk of an AI-written cover letter is not getting caught. It is sounding like everyone else. Here is what actually happens on the other side of the application, and how to use AI without sabotaging your shot."]},{"type":"h2","text":"Do companies actually check?"},{"type":"p","runs":["For the vast majority of roles, no one is running your cover letter through GPTZero or Originality.ai. Recruiters are reading dozens to hundreds of applications a day. They do not have time to copy paste each cover letter into a detector, and most ATS platforms do not include AI detection out of the box."]},{"type":"p","runs":["There are exceptions. Some academic, government, and consulting roles run formal integrity checks. A small but growing number of large employers use ATS features that flag suspected AI text. If you are applying to one of those, assume your letter will be screened. For everyone else, the question is not whether you will get caught, it is whether your letter will stand out."]},{"type":"h2","text":"Why AI detectors do not really work"},{"type":"p","runs":["AI detection tools claim accuracy rates of 95% or higher. In practice, peer-reviewed studies and the tools'' own disclaimers tell a different story."]},{"type":"list","ordered":false,"items":[["False positives are common. Detectors regularly flag human-written text, especially from non-native English speakers, as AI-generated."],["False negatives are easy. Light editing, asking the model for a different tone, or paraphrasing a single paragraph can drop detection confidence below the threshold."],["OpenAI shut down its own AI classifier in 2023 because it could not deliver reliable results. The third-party tools have not solved the problem since."]]},{"type":"p","runs":["A flag from a detector is rarely treated as a hiring veto. It is at most one signal among many, and most recruiters know not to rely on it alone."]},{"type":"h2","text":"What actually gets you screened out"},{"type":"p","runs":["The real giveaway is not formatting or word choice. It is content that could have been written about any company. The AI tell is generic. Lines like \"I am excited about this opportunity to contribute to your innovative team\" land identically in every inbox and signal nothing about you or this role."]},{"type":"callout","runs":["Recruiters do not need a detector to spot AI cover letters. They spot the ones that say nothing specific. A letter that names the team''s recent product launch, references a problem you know they are working on, or ties one of your concrete wins to their next quarter, those land regardless of how they were drafted."],"title":"The actual filter"},{"type":"h2","text":"How to use AI without sounding like AI"},{"type":"list","ordered":true,"items":[["Start from your own material. Paste your resume, your notes about the company, and the job description into the model. A cover letter generated from your real work history reads as yours; one generated from the job description alone reads as generic."],["Replace at least one paragraph by hand. The opening or the closing is best. Make it about something concrete: a specific reason you applied, a person you met, a product you used."],["Cut every sentence that could appear in someone else''s letter. If you can change the company name and the line still works for any company, delete it."],["Read it out loud. AI prose tends to over-hedge and over-qualify. Trim the soft openers (I believe, I think, perhaps) and the marketing words (innovative, dynamic, passionate)."],["Keep it short. Three short paragraphs that say something specific beat five polished paragraphs that say nothing."]]},{"type":"h2","text":"The rules to know"},{"type":"p","runs":["A handful of employers and most US federal agencies now ask you to disclose if AI was used to write your application. If the application asks, answer honestly. The disclosure is almost never disqualifying on its own, but lying about it can be. Read the application instructions before you submit."]},{"type":"h2","text":"The honest bottom line"},{"type":"p","runs":["Most employers will not detect an AI-written cover letter. They will detect a generic one. Use AI to overcome the blank page, then spend ten minutes making the letter specifically yours, specifically about them, and specifically shorter than it started. That is the version that gets read."]},{"type":"p","runs":["Offboard''s cover letter generator starts from your career memory and the role you are applying to, then asks you to add one specific thing only you could write. The point is not to bypass detection. It is to make sure the letter sounds like you on your best day, every time."]}]'::jsonb, 10),
  ('this-is-not-charity-it-is-reconstruction', 'This Is Not Charity. It Is Reconstruction.', 'essays', 'A raw, personal account of life after layoff: the rage, the despair, and the third path between torching everything and disappearing. Why Offboard exists.', '4 min read', '2026-04-16', 'Steph', 'Founder', null, ARRAY['we-forgot-to-reinforce-the-foundations', 'they-think-an-idea-is-bulletproof-they-are-wrong']::text[], 'published', '[{"type":"p","runs":["I took my job seriously."]},{"type":"p","runs":["Every shift was another brick in the wall I was building for my family. I wanted them to have stability, a roof that never leaked, and the kind of life where birthdays did not come with whispered calculations about whether we could afford cake. That was my north star."]},{"type":"p","runs":["Then the layoff notice came from a manager younger than me who could not perform the simplest tasks I handled daily. She signed the paperwork that ended my paycheck and kept climbing the corporate ladder anyway. In that moment, something inside me snapped. I did not torch the Amazon warehouse. I wanted to. The rage was real and raw."]},{"type":"p","runs":["But I also wanted to end my life."]},{"type":"p","runs":["That''s not theatre or clickbait. It''s how"," ",{"b":["MOST"]}," of the people who come to me feel after a layoff. Those two impulses sit side by side like twin demons whispering the same lie: nothing will ever change."]},{"type":"p","runs":["My children became the guardrails. They are the reason I woke up instead of doing the unthinkable. They are the reason I started volunteering more, and chose to breathe instead of break. That choice is the only reason I am still here to write this."]},{"type":"p","runs":["Yet every day I see the same story repeating across the country. People arrive at Offboard carrying the same two options in their hearts: torch the employer or die trying to stay loyal. There is almost nothing in between. The sentiment in the United States right now is that a revolution is either coming or already here."]},{"type":"p","runs":["It is not the kind with pitchforks in the streets yet."]},{"type":"p","runs":["It is quieter and more dangerous."]},{"type":"p","runs":["It is a digital Trail of Tears where entire families are displaced overnight by spreadsheets and quarterly earnings calls. Loyalty has been erased. Competence has been replaced by optics. And the managers who fail upward keep failing in fields like security, where the stakes are measured in human lives."]},{"type":"divider"},{"type":"h2","text":"History Offers a Different Map"},{"type":"p","runs":["History offers a different map. The stewards of great leadership were never the distant geniuses perched on thrones. They were the ones deep in the trenches. They built loyalty through a shared vision rather than fear. They managed rival personalities without creating chaos. They adapted to the crises of their time and turned pressure into forward momentum. Horatio Nelson did not win at sea by barking orders from afar. He made every sailor feel personally invested. George VI and Clement Attlee steadied nations through war and recovery by focusing on quiet competence and real delegation. Even in the most pressured environments, such as the Manhattan Project, leaders succeeded by aligning competing tribes around a clear purpose."]},{"type":"p","runs":["These patterns repeat because they work. Bad management is not inevitable. It is a choice made by people who prioritize stock prices over human stability."]},{"type":"divider"},{"type":"h2","text":"Why We Exist"},{"type":"p","runs":["That is why ",{"a":{"text":"we exist","href":"https://app.offboard.co/auth?tab=signup"}},"."]},{"type":"p","runs":["It is not another job board. It is the processing point we are modernizing for the digital age. We take the historical playbook of trench-level leadership and turn it into practical tools anyone can use the same day they lose their income. We give away the exact stabilization steps that communities share in their darkest moments:"]},{"type":"list","ordered":false,"items":[["File for unemployment immediately,"],["Rebuild the emergency fund even if it covers only one month,"],["Create a ruthless budget,"],["Update your resume and LinkedIn today,"],["Network by offering help first,"],["Talk to a lawyer or us before signing anything,"],["Protect mental health with a daily routine,"],["Pursue quick certifications,"],["Accept bridge work for cash flow,"],["Save every document before benefits expire."]]},{"type":"p","runs":["We embed the leadership lessons right alongside those steps so people see the gap between past stewards and present failures. The system that discarded you has officially been disrupted. My own layoff several years ago still fuels a chip on my shoulder the size of a warehouse. The incompetent manager(s) who ended my role now fail upward in security. That reality alarms me because it endangers everyone downstream."]},{"type":"p","runs":["Ironically, I was rooting for us to use the company that recently hired the bad apple, but now that I know they are a “cultural fit,” that meeting will never happen. I refuse to let that pattern continue unchecked."]},{"type":"divider"},{"type":"h2","text":"The Trojan Horse"},{"type":"p","runs":[{"a":{"text":"Offboard.Co","href":"https://newsletter.offboard.co/p/goldman-sachs-counted-the-bodies-16-000-jobs-a-month"}}," ","has become the Trojan horse that slips real recovery and real leadership wisdom into the hands of the hurting before they reach the torch or the end. We meet you exactly where you are. We hand you the guardrails you need when you feel too thin. We prove that the space between rage and despair can be filled with action that actually works."]},{"type":"p","runs":[{"b":["This is not charity."]}]},{"type":"p","runs":["It is reconstruction. Every person we stabilize today becomes the next steward who refuses to fail upward. Every family we keep intact becomes proof that loyalty can still exist when the right structures support it. The digital Trail of Tears need not be the final chapter. We can modernize the arms we carry. Not weapons of destruction but tools of survival and elevation."]},{"type":"p","runs":[{"a":{"text":"Offboard.Co","href":"/resources"}}," is that structure. It is built from the very pain I almost let consume me. And it sails because my children reminded me that the future is worth fighting for, even when the present feels unbearable. If you are reading this and carrying the same weight I once did, know this: you do not have to choose between torching everything or disappearing. There is a third path. It starts here."]}]'::jsonb, 11),
  ('a-series-of-fortunate-events', 'A Series of Fortunate Events', 'essays', 'The ones that feel like fate whispering “keep going.” A reflection on three serendipitous moments during Tech Week that rebooted a founder''s compass.', '3 min read', '2025-12-30', 'Steph', 'Founder', null, ARRAY['this-is-not-charity-it-is-reconstruction', 'the-mentor-trap-a-silicon-valley-horror-story']::text[], 'published', '[{"type":"p","runs":["Some years arrive like a half-written novel, and you spend them waiting for the plot to thicken."]},{"type":"p","runs":["2025 was mine."]},{"type":"p","runs":["At the end of Q3, I was coming off a brutal stretch of fundraising that wasn''t really fundraising at all, just a lot of “no''s” because my ethics wouldn''t let me take money from the wrong hands. I was bone-tired, second-guessing every pitch deck, and yeah, Mercury was in retrograde, which for a Monday felt like the universe''s polite way of saying “",{"b":["stay in bed."]},"”"]},{"type":"p","runs":["But destiny, it turns out, doesn''t take RSVPs. Instead, it handed me 3 moments so serendipitous, so alive with the right energy, that I couldn''t have scripted them better if I''d tried."]},{"type":"p","runs":["They weren''t just events; they were lifelines, pulling me back into the joy of building with people who get it."]},{"type":"p","runs":["We kicked off ",{"a":{"text":"Tech Week","href":"https://sf-techweek.com/"}}," with"," ",{"a":{"text":"Mercury","href":"https://mercury.com/"}},"''s Brunch and Water Cycling on the Bay. A Monday (oof), but pedal-powered adventure departing from Pier 40, complete with guided rides every 20 minutes, networking bites, lawn games, and that rare merch you actually want to wear."]},{"type":"p","runs":["I almost bailed."]},{"type":"p","runs":["The year''s betrayals had me in full hermit mode, and who water-cycles on a Monday when your soul needs a nap? But something, call it a rogue wave of optimism, pulled me there."]},{"type":"p","runs":["We were out on the Bay, legs pumping these"," ",{"a":{"text":"floating bikes","href":"https://spinoutfitness.com/"}}," like we were surfing spreadsheets, the city skyline blurring into possibility. That''s when I met her: another female founder, mid-ride, both of us ditching the investor small talk for a full-on nerd-out about GTM sales models. She mapped her churn strategies on a napkin (okay, a soggy coaster), I countered with my retention hacks, and for two hours, we forgot the whole point was supposed to be chasing checks."]},{"type":"p","runs":[{"i":["Could life be any more perfect?"]}]},{"type":"p","runs":["The wind in our hair, the water beneath us, and a connection that felt like the first real yes of the year. Thank you, Mercury, for turning a hesitant Monday into the kind of magic that reboots your compass. My legs were screaming, but the views were worth every burn. By the time we rolled back into"," ",{"a":{"text":"Frankie''s","href":"https://www.frankiessf.com/"}},", my phone was heavier with intros than regrets, and the air hummed with that electric “",{"b":["we''re in this together"]},"” vibe. It was the perfect wave to pedal new connections, reminding me that progress isn''t a solo sprint, it''s a group ride."]},{"type":"p","runs":["Then came the"," ",{"a":{"text":"Graham and Walker","href":"https://grahamwalker.com/blog/inside-west-coast-founder-day-2025-why-these-rooms-move-founders-forward/"}}," ","event, a breath of fresh air after the chaos of a morning gone rogue."]},{"type":"p","runs":["I''d rushed across town, misplaced my purse in a frenzy to get the kids out the door for school, it was"," ",{"a":{"text":"RAINING IN THE BAY","href":"https://www.msn.com/en-us/weather/topstories/something-big-is-blocking-california-s-winter-storms-here-s-what-that-means/ar-AA1RqofD"}},", so I arrived frazzled, equal parts caffeine and"," ",{"a":{"text":"imposter syndrome","href":"https://awbw.org/facing-imposter-syndrome/"}},"."]},{"type":"p","runs":["But walking into that room?"]},{"type":"p","runs":["It was like sinking into a warm bath after a cold hike. These women are calm, wise, and unapologetically present. They met me exactly where I was, no judgment, just"," ",{"a":{"text":"grace","href":"https://women-in-tech.org/"}},"."]},{"type":"p","runs":["We talked ethics in fundraising over honeyed tea (literal and figurative), shared the quiet victories of saying no to bad fits, and laughed about the absurdities of it all. It was the flame I needed on my team, that soft fierceness that says, “You''re not alone, and you''re enough.” I left steadier, taller, ready to face the week''s whirlwind with a little less armor."]},{"type":"p","runs":["And the grand finale, the one I hesitated on the most:"]},{"type":"p","runs":[{"a":{"text":"FounderNexus''s SF Grand Opening","href":"https://www.linkedin.com/posts/court-lorenzini-333447_sf-grand-opening-foundernexus-luma-activity-7395902251522908160-VvNa"}},", a gathering for founders in a space that felt like the future unfurling."]},{"type":"p","runs":["I''d stared at the invite for days."]},{"type":"p","runs":["Exhausted from the week''s highs, tempted to curl up with takeout instead. But I went, and from the first handshake, time seemed to stop."]},{"type":"p","runs":["There, amid the hum of real builders trading blueprints for better worlds, I glimpsed the next 12 months tilting into focus. Partnerships crystallizing. Ideas igniting. A ripple effect that could shift not just my path, but humanity''s."]},{"type":"p","runs":["It was one of those rare moments where you know, deep in your bones, that everything is aligning, that the frequency you''re on is pulling in the right souls for the long haul."]},{"type":"p","runs":["Thank you, ",{"a":{"text":"FounderNexus","href":"https://foundernexus.com/"}},", for that pivotal moment."]},{"type":"p","runs":["These weren''t accidents. They were deliberate threads in a tapestry"," ",{"a":{"text":"woven by communities","href":"https://anagomarketing.co.za/why-community-is-the-2025-buzzword-that-actually-matters-and-how-to-build-one-that-lasts/"}}," ","who choose generosity over gatekeeping, ethics over expediency."]},{"type":"p","runs":["To every builder who hosted the brunch, the COS or EA that mapped the Luma or Partiful route, started the coffee, or opened the door to that grand space, thank you."]},{"type":"p","runs":["Thank you for helping without hesitation, for standing firm when the world rewards shortcuts."]},{"type":"p","runs":["You are the exact kind of humans I''d choose, no question, if we ever get to colonize a new Earth."]},{"type":"p","runs":["You are ethical architects turning grind into grace. May 2026 bring more of these waves, more rooms full of that frequency, more of us building the world we actually want."]},{"type":"p","runs":["Here''s to the fortunate events that feel like home."]},{"type":"p","runs":["And to the ones still coming."]}]'::jsonb, 12),
  ('they-think-an-idea-is-bulletproof-they-are-wrong', 'They Think an Idea is Bulletproof. They Are Wrong.', 'essays', 'This essay calls out the myth of a “bulletproof” AI future and the VC playbook that treats workers as expendable. It ends with a concrete IC playbook that flips the script.', '5 min read', '2025-09-29', 'Steph', 'Founder', null, ARRAY['we-forgot-to-reinforce-the-foundations', 'the-valleys-hypocrisy-hustle-exposed-by-the-overemployed']::text[], 'published', '[{"type":"h2","text":"They Think an Idea is Bulletproof. They Are Wrong."},{"type":"p","runs":["Beneath the mask of “AI efficiency” and “corporate restructuring” is the flesh-and-blood of thousands. An idea of a future without their workers has been planted. But ideas can be changed."]},{"type":"blockquote","runs":["Artists use lies to tell the truth, while politicians use them to cover the truth up. -Evey Hammond, V for Vendetta"]},{"type":"h2","text":"Your Government Told You to Remember"},{"type":"p","runs":["The guy who was brutally murdered at Turning Point USA, but not to remember the"," ",{"a":{"text":"13,000 humans out of work.","href":"https://www.cnn.com/business/live-news/us-jobs-report-august-2025"}}," ","In June, for the first time in years, the economy did not just stagnate, it actively bled 13,000 jobs. This was not an act of God, but rather a matter of policy. Do you know of no reason why this"," ",{"a":{"text":"treason against the worker","href":"https://www.nbcnews.com/business/economy/911000-fewer-jobs-created-april-2024-march-2025-bls-says-rcna230065"}}," ","should ever be forgotten?"]},{"type":"h3","text":"They Wear the Mask of Profit. We Are the Face Beneath It."},{"type":"p","runs":[{"a":{"text":"Companies","href":"https://intellizence.com/insights/layoff-downsizing/major-companies-that-announced-mass-layoffs/"}}," ","like Salesforce and Amazon speak of an AI-driven future with"," ",{"a":{"text":"fewer people","href":"https://www.businessinsider.com/recent-company-layoffs-laying-off-workers-2025"}},". They claim that AI will not replace people, but rather that"," ",{"a":{"text":"those who use AI will replace those who do not","href":"https://hrspotlight.com/from-layoffs-to-lifelines-how-companies-are-supporting-workers-in-2025/"}},". This is a paradox they hope you won''t question. They forget that a symbol, like a company''s value, is"," ",{"a":{"text":"given power by people","href":"https://medium.com/movie-quotes/v-for-vendetta-quotes-e9e9a884306c"}},". Alone, it is meaningless."]},{"type":"p","runs":[{"b":["An Auspicious Opportunity: 911,000 Fewer Reasons to Trust Their Lies."]}]},{"type":"p","runs":["The Bureau of Labor Statistics itself revised a year of job growth downward by"," ",{"a":{"text":"911,000 positions","href":"https://www.nbcnews.com/business/economy/911000-fewer-jobs-created-april-2024-march-2025-bls-says-rcna230065"}},". The picture was always bleaker than they painted. When the truth is unveiled, what will you do? Will you allow this series of unfortunate events to pass unmarked?"]},{"type":"p","runs":[{"b":["They Promise Order, They Demand Your Silent Consent."]}]},{"type":"p","runs":["The narrative is one of fear: fear of economic uncertainty and fear of being left behind by technological advancements. This fear has become the ultimate tool. But ask yourself:"," ",{"a":{"text":"who benefits from this silence?","href":"https://www.forbes.com/sites/jackkelly/2025/05/10/big-layoffs-are-hitting-these-sectors-the-hardest/"}}]},{"type":"h3","text":"Read Between the Lines:"},{"type":"p","runs":["When a company cites “low attrition” or the need to become “future-ready,” consider what is unsaid. Often, this is code for protecting profits and shareholder value above the well-being of people."]},{"type":"divider"},{"type":"h2","text":"The Dark VC Money Playbook (Q3-Q4 2025)"},{"type":"p","runs":[{"b":["1."," ",{"a":{"text":"The AI Feeding Frenzy","href":"https://www.svb.com/news/company-news/ai-continues-to-fuel-us-vc-investment-despite-higher-burn-rates-silicon-valley-bank-releases-latest-state-of-the-markets-report/"}}]}]},{"type":"list","ordered":false,"items":[[{"b":["The Spicy Take:"]}," VCs are creating a bubble by dumping capital into a handful of unproven AI giants, starving all other sectors of oxygen and innovation."],[{"b":["The Evidence:"]}," AI companies now account for"," ",{"b":["58 cents of every VC dollar"]}," ",{"a":{"text":"deployed in 2025","href":"https://www.theventure.city/reports/2025/vc-benchmark-q2-2025"}},", despite often having higher burn rates than actual revenue."]]},{"type":"p","runs":[{"b":["2. The Mega-Fund Monopoly"]}]},{"type":"list","ordered":false,"items":[[{"b":["The Spicy Take:"]}," Power is consolidating into a few massive funds that are dictating the future of tech based on a narrow, self-serving worldview. It''s a closed circle."],[{"a":{"text":"The Evidence:","href":"https://www.svb.com/news/company-news/ai-continues-to-fuel-us-vc-investment-despite-higher-burn-rates-silicon-valley-bank-releases-latest-state-of-the-markets-report/"}}," ","A staggering one-third of all U.S. VC investment in 2025 came from deals involving just the ",{"b":["six largest funds"]},"."]]},{"type":"p","runs":[{"b":["3."," ",{"a":{"text":"The Diversity Squeeze","href":"https://afrotech.com/op-ed-venture-capitals-decline-damages-black-dealmakers-ideas"}}]}]},{"type":"list","ordered":false,"items":[[{"b":["The Spicy Take:"]}," The “downturn” is being used as an excuse to crush Black and emerging fund managers, systematically killing a diversity of ideas before they can even start."],[{"b":["The Evidence:"]}," Funding for emerging managers (a key source of diversity) has plummeted from"," ",{"b":["$64B in 2021 to just $4.7B"]}," so far in 2025."]]},{"type":"p","runs":[{"b":["4."," ",{"a":{"text":"The Rug-Pull Layoffs","href":"https://techcrunch.com/2025/09/22/tech-layoffs-2025-list/"}}]}]},{"type":"list","ordered":false,"items":[[{"b":["The Spicy Take:"]}," After years of pushing “growth at all costs,” VCs are now forcing portfolio companies to make deep, sudden cuts-sacrificing workers to extend their own financial runway."],[{"a":{"text":"The Evidence:","href":"https://www.forbes.com/sites/donmuir/2022/12/02/startups-facing-mass-layoffs-as-vc-firms-reverse-course/"}}," ","Over ",{"b":["22,000 tech layoffs"]}," in 2025 are a direct result of this sudden, VC-mandated pivot to “efficiency” and profitability."]]},{"type":"divider"},{"type":"h2","text":"How to Read the VC Playbook"},{"type":"p","runs":["The moves above aren''t random; they''re a calculated response to a new economic reality. Here''s the dark logic behind them:"]},{"type":"list","ordered":false,"items":[[{"b":["The AI Gambit is a Hail Mary"]},": VCs are piling into AI because they need a narrative of “transformative potential” to justify massive valuations in a shaky market. The high burn rates (the median Series A AI company burns"," ",{"b":["$5 to gain $1 of new revenue"]},") are waved away as the cost of funding the future. It''s a high-risk bet that the AI boom will create the outsized returns they can''t find elsewhere."],[{"b":["Consolidation is a Shield Against Losses"]},": With the IPO window only “cracking open” and LPs demanding returns, mega-funds are circling their wagons. They''re backing proven late-stage companies because early-stage bets are now too risky. This isn''t about funding innovation; it''s about capital preservation and maintaining a strong image for their own investors."],[{"b":["The ''Efficiency'' Push is a Euphemism for Survival"]},": The sudden pivot from growth to profitability is a direct order from VCs who can no longer afford to prop up struggling startups. The massive layoffs you see at tech companies are the direct result of VCs pulling the rug out, telling founders to cut burn rate immediately or face extinction. The human cost is collateral damage."]]},{"type":"divider"},{"type":"h2","text":"How to Follow the Dark Money"},{"type":"p","runs":["If you want to track this in real-time, don''t just watch the press releases; also monitor the company''s official website for updates. Search for their name on Twitter. Monitor layoff trackers like"," ",{"a":{"text":"WarnTracker","href":"https://www.warntracker.com/"}},". Listen to the earnings calls where CEOs tout “AI efficiency” as a reason for headcount reduction. And pay attention to the funding rounds! When you see a billion-dollar AI deal, ask which sectors ",{"i":["aren''t"]}," getting funded as a result."]},{"type":"p","runs":["This isn''t just a market correction; it''s a fundamental reordering of Silicon Valley''s power structure, leaving many people behind."]},{"type":"p","runs":["I know what you''re thinking."]},{"type":"p","runs":[{"i":["“Sounds awful, Steph.”"]}]},{"type":"p","runs":["Yes, ",{"b":["it is"]},", BUT! I have a workaround!"]},{"type":"divider"},{"type":"h2","text":"The IC''s Playbook: Turning the Tables in the Dark Money Game"},{"type":"p","runs":["The VC playbook is designed to make you a disposable asset. Your playbook is about making yourself an indispensable, untouchable force. Here''s how you fight back, starting today."]},{"type":"h3","text":"1. Against the AI Feeding Frenzy: Weaponize AI for Your Own Leverage."},{"type":"list","ordered":false,"items":[[{"b":["Their Game:"]}," Pour billions into AI to eventually replace you."],[{"b":["Your Move:"]}," Become so proficient with AI that you become the architect of the new system, not its victim."],[{"b":["Actionable Steps:"]},{"list":{"ordered":false,"items":[[{"b":["Become an In-House AI Expert:"]}," ","Don''t wait for training. Identify one high-value, repetitive task in your workflow (e.g., code review, generating marketing copy, analyzing customer support tickets) and master an AI tool that automates it. Document the time saved and present it as a win."],[{"b":["Shift Your Title:"]}," Start referring to yourself as an “AI-Augmented [Your Role].” This immediately reframes you from a cost to be cut to an innovator leveraging the latest technology."],[{"b":["Build an AI Portfolio:"]}," ","Use public AI models to create sample projects that demonstrate tangible business value. This isn''t for your current job; it''s for your next one, demonstrating your ability to deliver more with these tools."]]}}]]},{"type":"h3","text":"2. Against the Mega-Fund Monopoly: Build Your Own Decentralized Network."},{"type":"list","ordered":false,"items":[[{"b":["Their Game:"]}," Consolidate power so your career depends on their whims."],[{"b":["Your Move:"]}," Create a power base so independent and robust that their influence becomes irrelevant to you."],[{"b":["Actionable Steps:"]},{"list":{"ordered":false,"items":[[{"b":["Go Beyond LinkedIn:"]}," ","Build genuine connections in communities like"," ",{"a":{"text":"Offboard","href":"/#community"}},". These are your real safety net."],[{"b":["Create a “Personal Board of Directors”:"]}," ","Identify 3-5 people across different industries who you trust. Meet with them quarterly. Share intel. This is your decentralized advisory network-no VC fund required."],[{"b":["Build in Public:"]}," Share your projects, your learnings, and your failures in places where your work speaks for itself (GitHub, a personal blog, Substack). This creates an independent reputation that no layoff can take from you."]]}}]]},{"type":"h3","text":"3. Against the Diversity Squeeze: Invest in the Counter-Economy."},{"type":"list","ordered":false,"items":[[{"b":["Their Game:"]}," Defund diverse innovation and consolidate power among the usual suspects."],[{"b":["Your Move:"]}," Actively support and participate in the ecosystems they''re trying to starve."],[{"b":["Actionable Steps:"]},{"list":{"ordered":false,"items":[[{"b":["Mentor Relentlessly:"]}," ","Offer your time to mentorship programs for underrepresented groups in tech (",{"a":{"text":"Code Tenderloin","href":"https://www.codetenderloin.org/"}},","," ",{"a":{"text":"US Digital Response","href":"https://www.usdigitalresponse.org/volunteer"}},"). Your knowledge is currency; spend it where it counters their narrative."],[{"b":["Patronize Alternative Economies:"]}," ","When considering your next move, actively research startups funded by emerging managers, diverse-led VCs, or employee-owned cooperatives. These companies often have more resilient, human-centric cultures."],[{"b":["Amplify Diverse Voices:"]}," ","Use your reach (even a small one) to share the work and achievements of founders and ICs from underrepresented backgrounds. Algorithms favor engagement; give them some."]]}}]]},{"type":"h3","text":"4. Against the Rug-Pull Layoffs: Operate Like a Free Agent."},{"type":"list","ordered":false,"items":[[{"b":["Their Game:"]}," Keep you dependent and fearful, so you accept worse conditions."],[{"b":["Your Move:"]}," Embrace the mindset that your current job is a “project” or a “client,” not your identity. Your loyalty is to your skills and your network, not to a logo."],[{"b":["Actionable Steps:"]},{"list":{"ordered":false,"items":[[{"b":["Maintain a “Continuous Interview” Loop:"]}," ","Even if you''re happy, take 1-2 exploratory calls per month. This does two things: it keeps your interview skills sharp, and it provides you with real-time data on your market value, helping to strip away fear."],[{"b":["Know Your “Walk-Away” Number:"]}," ","Calculate the exact financial runway you need to be comfortable (6-12 months of expenses). This number is your psychological armor. It transforms a layoff from a crisis into a planned transition."],[{"b":["Become an “Impact Sniper”:"]}," ","In your current role, don''t just do your job. Relentlessly tie your work to measurable business outcomes (revenue saved, revenue generated, time saved). You''re not an employee; you''re a vendor of quantifiable results. It''s much harder to cut a vendor who can directly prove their value."]]}}]]},{"type":"divider"},{"type":"h2","text":"TL;DR"},{"type":"p","runs":["They want you to see yourself as a line item. Your mission is to consistently prove that you are the source of the value itself. This isn''t just about keeping a job; it''s about reclaiming your agency in a system designed to strip it from you."]},{"type":"p","runs":["Remember: Your most powerful act of resistance is to"," ",{"b":["make yourself impossible to replace."]}]}]'::jsonb, 13),
  ('we-forgot-to-reinforce-the-foundations', 'We Forgot to Reinforce the Foundations', 'essays', 'The tech industry treated layoffs like a spreadsheet exercise and forgot the human foundations that keep the whole thing standing. A call to patch the system with people.', '3 min read', '2025-08-20', 'Steph', 'Founder', null, ARRAY['this-is-not-charity-it-is-reconstruction', 'they-think-an-idea-is-bulletproof-they-are-wrong']::text[], 'published', '[{"type":"h2","text":"Hello, friend."},{"type":"p","runs":["You''re reading this on a screen. Maybe it''s the one you use to code, to design, to strategize, to deploy. The one that glows with the promise of disruption. The one that just delivered a terse, HR-sanctioned email that began, “As part of a strategic restructuring…”"]},{"type":"p","runs":["Yeah. I know."]},{"type":"p","runs":["Look around. The air in the tech sphere is getting thin. Can you feel it?"]},{"type":"p","runs":["That low, persistent hum isn''t just the server farm downstairs. It''s the collective anxiety of an entire industry holding its breath, waiting for the next shoe to drop. We built this digital empire on lines of code and promises of changing the world, but we forgot to reinforce the foundations."]},{"type":"p","runs":["The human ones."]},{"type":"p","runs":["They call it a “headcount reduction.” A “right-sizing.” A “correction.” They use clean, sterile language that scrubs away the messiness of a shattered identity, the cold sweat of a mortgage payment with no income, the silent scream into a pillow after updating a LinkedIn profile for the hundredth time."]},{"type":"p","runs":["This is not a correction. This is a mass psychic event. A silent, sanctioned crash. And they''re just… ignoring it. They''re offering severance packages and generic transition help like a bandage on a gunshot wound. They''re talking about “leaning out” and “doing more with less” while the “less” are people who gave their twenties, their health, their passion to building someone else''s dream."]},{"type":"p","runs":["I see them. I talk to them every day at Offboard. They''re not just resumes in a database. They''re the brilliant minds who architected the systems we can''t live without."]},{"type":"p","runs":["They''re the legacy talent."]},{"type":"p","runs":["The ones with the institutional memory that can''t be forked and merged from a GitHub repo. And they are hurting. Right under our noses. In the Slack channels that just went quiet. In the 1:1s that got abruptly canceled. In the apartment down the hall, where a person is actively fighting the thought that they are now, and perhaps always were, a line item to be cut."]},{"type":"p","runs":["This system is sick. And it''s making us sick."]},{"type":"p","runs":["We can''t just wait for the C-suite to develop a conscience. They''re optimizing for shareholder value, not sanity. So we have to do what we''ve always done."]},{"type":"p","runs":["We have to build a patch."]},{"type":"p","runs":["A human patch."]},{"type":"p","runs":["I''m calling for volunteers. Not for a hackathon. For a lifeline."]},{"type":"p","runs":[{"b":["Journalists."]}," We need you. Not for another think-piece about market trends. We need you to be scribes for the truth. To document the human cost. To give a voice to the ones who signed NDAs along with their termination papers. Shine a light into the dark corners of the non-disparagement clauses. Tell their stories. Make it impossible to ignore."]},{"type":"p","runs":[{"b":["Therapists."]}," We need you. Your skills are more critical than any new JavaScript framework. We need you to volunteer your time, your expertise, and your empathy. We need pro-bono sessions, group workshops, and crisis resources tailored to the specific, soul-crushing paradox of being deemed “redundant” when you''ve never worked harder in your life. Help them understand they are not the error. The system is."]},{"type":"p","runs":["This is the call: ",{"b":["be there"]}," for those who are hurting the most. You don''t need to look far. They are your former colleagues. Your network. Your friends."]},{"type":"p","runs":[{"i":["They''re the ones who just got very, very quiet."]}]},{"type":"p","runs":["Don''t just send a “Hey, hope you''re ok” LinkedIn message."," ",{"b":["Call."]}," ",{"i":["Show up"]},"."," ",{"b":["Listen"]},". Buy them coffee and let them not talk about LeetCode. Remind them that their worth was never stored in a Jira ticket."]},{"type":"p","runs":["We have to keep this talent in the arena. Because the next hit… the next hit could put them out for good. And we can''t afford to lose them. We just can''t see it yet."]},{"type":"p","runs":["The attack is on the human spirit. It''s time we fought back."]},{"type":"p","runs":["Be there."]},{"type":"p","runs":["(You know where to find us.)"]}]'::jsonb, 14),
  ('the-mentor-trap-a-silicon-valley-horror-story', 'The Mentor Trap: A Silicon Valley Horror Story', 'essays', 'Why grown adults shouldn''t need babysitters with black books. A raw take on predatory mentorship in VC culture and a call for accountability.', '3 min read', '2025-07-27', 'Steph', 'Founder', null, ARRAY['the-valleys-hypocrisy-hustle-exposed-by-the-overemployed', 'a-series-of-fortunate-events']::text[], 'published', '[{"type":"h2","text":"Why Grown-Ass Adults Shouldn''t Need Babysitters with Black Books","id":"why-grown-ass-adults-shouldnt-need-babysitters"},{"type":"p","runs":["I''m 39. It''s time I quit protecting buzzards in Patagonia vests. Done with the errors."]},{"type":"p","runs":["The “Me Too” reckoning in tech?"]},{"type":"p","runs":["Overdue."]},{"type":"p","runs":["Like a system update 10 years past EOL, it''s time we finally start tightening down VC culture, disclosing YC''s golden boys turned predators."]},{"type":"p","runs":["But it makes you ask: Why the fuck do we need mentors at all?"]},{"type":"p","runs":["Think about it. Silicon Valley worships the college dropout. Puts them on a pedestal. But dare you build without some “seasoned” guide whispering in your ear? Suddenly, you''re radioactive. Invisible. A ghost in the machine."]},{"type":"p","runs":["Your worth isn''t your vision."]},{"type":"p","runs":["Not your code."]},{"type":"p","runs":["Not your grit."]},{"type":"p","runs":[{"b":["It''s who talks about you in rooms you''re locked out of."]}]},{"type":"p","runs":["That''s the price of admission. The dirty little secret behind every “win.”"]},{"type":"p","runs":["Someone recently asked me, “Why does a 39-year-old woman need a mentor?”"]},{"type":"p","runs":["My answer was the cold, hard truth:"]},{"type":"p","runs":["“It''s chess.”"]},{"type":"p","runs":["When you''re building something that didn''t exist yesterday, you need someone who has already broken ground. Someone with power. Money. Influence. A bat that''s already hit out of the park. They move pieces you can''t touch."]},{"type":"p","runs":[{"b":["That''s the game."]}]},{"type":"p","runs":["But ",{"i":["why"]},"?"]},{"type":"p","runs":[{"i":["Why"]}," is the game a ",{"i":["hunting"]}," ground?"]},{"type":"p","runs":[{"i":["Why"]}," do female founders get preyed on like vulnerabilities in beta code?"]},{"type":"p","runs":["I know the pattern."]},{"type":"p","runs":["The peak? COVID. Isolation. The perfect exploit. They made their move. Made it clear:"," ",{"i":["Funding flowed where flesh did. A transaction disguised as mentorship. A backdoor into your integrity."]}]},{"type":"p","runs":["Repellent. Degrading."]},{"type":"p","runs":["Not surprising, on any level."]},{"type":"p","runs":[{"i":["Why"]}," did I play chess?"," ",{"b":["For money, of course"]},". (Once a Hooter''s girl, always a Hooter''s girl.)"]},{"type":"p","runs":["And when the pattern glitched into view? I didn''t break. I compiled. Started plotting. How do I shield the next wave? The brilliant minds building in SF, NYC, Miami, London, Sydney?"]},{"type":"p","runs":[{"b":["They don''t need a fucking mentor."]}]},{"type":"p","runs":["Not the kind Silicon Valley peddles. And it''s not just the men. Plenty of women, too. Masters of psychological DDoS attacks. Time vampires. Soul miners."]},{"type":"p","runs":["So here''s the question, Valley:"]},{"type":"p","runs":["How do we audit this rot?"]},{"type":"p","runs":["Mentor credibility shouldn''t be less verified than a fucking Stanford degree. We need accountability. Real consequences. If your assigned “guide” tries to exploit you: psychologically, financially, physically, sexually, they should burn. Not getting a quiet exit package and a new LLC."]},{"type":"p","runs":["My safeguards? Age. Over 30. The frontal lobe is mainly formed. Marriage. Kids. People who''d notice if I vanished."," ",{"b":["Guardrails"]},"."]},{"type":"p","runs":["But what about the solo players?"]},{"type":"p","runs":["The naive ones?"]},{"type":"p","runs":["The ones nobody looks for?"]},{"type":"p","runs":["The ones desperate for that ",{"i":["flash cash"]}," just to survive? That''s the exploit. That''s the zero-day they weaponize."]},{"type":"p","runs":["This is a long game. And they play it in the dark. Usually on Signal."]},{"type":"p","runs":["So I''m asking you, Silicon Valley:"]},{"type":"p","runs":["Did your mentor make you do something dark for the check?"]},{"type":"p","runs":["Slide into my DMs. ",{"i":["Send the corruption receipts."]}," Anonymized. Encrypted. I don''t care."]},{"type":"p","runs":["Or did ",{"i":["you"]}," keep that loop going?"]},{"type":"p","runs":["And ask yourself:"]},{"type":"p","runs":["Do grown-ass adults – builders, creators, fucking founders...do they really need babysitters with black books?"]},{"type":"p","runs":["Or is the “mentor” myth just the prettiest lie in a system running on predatory code? Startup sex trafficking? Allegedly."]},{"type":"p","runs":[{"b":["Time for a hard reboot."]}]},{"type":"p","runs":["// End Transmission"]}]'::jsonb, 15),
  ('the-valleys-hypocrisy-hustle-exposed-by-the-overemployed', 'The Valley''s Hypocrisy Hustle Exposed by the Overemployed', 'essays', 'How the overemployed cracked the system and turned hustle culture into a joke. An expose on Silicon Valley''s class war and the workers fighting back.', '4 min read', '2025-07-23', 'Steph', 'Founder', null, ARRAY['the-mentor-trap-a-silicon-valley-horror-story', 'they-think-an-idea-is-bulletproof-they-are-wrong']::text[], 'published', '[{"type":"p","runs":["We''re going root access on the Old Guard and starting at the top. We''re not poking the bear - we''re jamming a corrupted payload straight into its arrogance core."]},{"type":"p","runs":["Prepare for uncompromising R&D. How exactly does the Sand Hill Road treehouse clique suffocate the talent beneath them? It suffocates them with rent extracted like blood tithes, with burnout mandated like scripture, with futures traded on rigged tables."]},{"type":"p","runs":["The rot isn''t spreading;"," ",{"b":["it ",{"i":["is"]}," the foundation."]}]},{"type":"divider"},{"type":"h2","text":"// EXPLOIT: HYPOCRISY_HUSTLE.virus (Class War Variant)","id":"exploit-hypocrisy-hustle"},{"type":"p","runs":[{"b":["The circus is in town. Clowns have root privileges."]}]},{"type":"list","ordered":false,"items":[[{"b":["Target A: Roy Lee''s “Cluely”"]},{"br":true},"a16z pumped $15M into its toxic core. Their growth hack?"," ",{"i":["Industrialized virality"]}," - fifty interns, two hundred spam videos daily, bragging about “cheating on everything.” Pure digital effluent."],[{"b":["Target B: Soham Parekh"]},{"br":true},"Indian engineer who mastered the remote/AI grind. Juggled four-plus YC gigs, raking in ₹2.5 lakh a day until CEOs cried “liar” on their blue-check feeds. Crucified."]]},{"type":"p","runs":["The beautiful, sick irony?"]},{"type":"list","ordered":false,"items":[["Lee''s “strategy” = lap-dance videos, expulsion lore, “provocation-as-growth.” VCs call it genius, bold, visionary, showering him in term-sheet confetti."],["Parekh plays the exact same corrupted game ="," ",{"b":["SCAMMER."]}," Digital scarlet letter. No confetti, just ashes."]]},{"type":"p","runs":["The root rot traces upward:"]},{"type":"blockquote","runs":["a16z''s Marc Andreessen sits on eight-plus boards and preaches “founder focus” while his own attention is fragmented across a bloated portfolio. They fund Lee''s “cheat on everything” ethos, then act shocked when talent weaponizes the exploit. The rulebook is clear:"," ",{"b":["disruption is divine only when it enriches them."]}," ","When workers flip the script - burn the heretic. Standard op."]},{"type":"divider"},{"type":"h2","text":"// ANALYSIS: DIGITAL_SERFDOM.exe (Runtime: Neo-Feudal)","id":"analysis-digital-serfdom"},{"type":"p","runs":["Silicon Valley''s ",{"i":["Hustle Porn"]}," is opiate code, glorifying 80-hour weeks and sleeping under desks, masking the real payload:"," ",{"b":["Neo-Feudal Serfdom."]}," The Overemployed are the counter-exploit - rootkit resistance."]},{"type":"h3","text":"1. HUSTLE_PORN.FACADE (Decompiling the Lie)"},{"type":"list","ordered":false,"items":[[{"b":["Performance of Productivity"]}," - 12-hour shifts rebranded as “purpose.” Industrial-Revolution labor models with ping-pong tables. Wages suppressed while inflation eats them alive."],[{"b":["Mimetic Malware"]}," - Engineered desire: covet the equity carrot, chase the promotion status symbol, a distraction from wage decay."],[{"b":["The Burnout Engine"]}," - Loyalty weaponized. “Be an over-achiever!” until you''re Boxer from"," ",{"i":["Animal Farm"]}," - worked to death, then discarded. Productivity dips? You''re legacy code."]]},{"type":"h3","text":"2. SERFDOM_CORE (Runtime Manifest)"},{"type":"list","ordered":false,"items":[[{"b":["Land:"]}," company tools and systems - you build on their sandbox, you own nothing"],[{"b":["Obligations:"]}," non‑competes and forced arbitration - digital shackles"],[{"b":["Lord Protections:"]}," at‑will employment - they can"," ",{"code":"rm -rf /your_life"}," ","anytime"],[{"b":["Surveillance:"]}," keyloggers and productivity spyware - Panopticon 2.0 (see IAG Insurance)"],[{"b":["Golden Handcuffs:"]}," stock options and free kombucha - cages disguised as perks"],[{"b":["Wage Suppression Cartels:"]}," ","Apple and Google collude to cap salaries"],[{"b":["Knowledge Enclosure:"]}," your output becomes their property; you build the kingdom, you get evicted"]]},{"type":"h3","text":"3. OVEREMPLOYED_RESISTANCE.ko (Counter-Exploit Loaded)"},{"type":"list","ordered":false,"items":[[{"b":["Income Diversification"]}," - J1 + J2/J3 = financial resiliency. $750K in 2023 broke feudal dependency."],[{"b":["Tech-Enabled Subversion"]}," - KVMs for meeting overlap, calendar fuzz, agile sprints exploited across multiple fronts."],[{"b":["Ideological Rewrite"]}," - Corporate loyalty is malware; pre-industrial artisans had it right: sell labor to multiple buyers."]]},{"type":"h3","text":"4. TENSION & ETHICAL_FALLOUT (Runtime Errors)"},{"type":"list","ordered":false,"items":[[{"b":["Detection Vectors"]}," - 91 percent of AU firms spy on workers; colleagues spot dual calls; retaliation guaranteed."],[{"b":["The “Time Theft” Argument"]}," ","- Critics claim it hurts others reliant on remote work. Counter: underutilization is the real theft - offices average three productive hours a day."],[{"b":["Sustainability Hack"]}," - It''s not 70-hour hell. It''s efficiency: automate, delegate, solve tough problems in sprints, then they leave you alone."," ",{"i":["Output > Hours."]}]]},{"type":"h3","text":"5. SYSTEMIC_SHIFT (Payload Detonated)"},{"type":"list","ordered":false,"items":[[{"b":["Labor''s Revenge"]}," - Applying cold profit logic back onto capitalists. Jobs become revenue streams; nothing personal."],[{"b":["Remote Work''s Double-Edged Sword"]}," ","- Employers demanded always-on flexibility; workers weaponized it."],[{"b":["NPQOL Revolution"]}," - Net Present Quality of Life. Time is the scarce asset; helping a friend outranks low-impact corporate tasks."]]},{"type":"divider"},{"type":"h2","text":"// FINAL TRANSMISSION","id":"final-transmission"},{"type":"p","runs":["The overemployed are not hiding; they''re exposing the theater. Hustle culture is a render, a distraction loop. They redefine value by"," ",{"b":["output"]}," and"," ",{"b":["autonomy seized"]},"."]},{"type":"p","runs":["Surveillance tightens. RTO mandates escalate. Same as it ever was."," ",{"i":["Pullman Strike"]}," logic vibrates in the server hum:"]},{"type":"p","runs":["Labor doesn''t beg for scraps. Labor negotiates power - usually with teeth."]},{"type":"h2","text":"// END TRANSMISSION // ENCRYPT // SHADOW //","id":"end-transmission"}]'::jsonb, 16),
  ('alameda-d2-safety-net-transparency', 'She won on the safety net. Three weeks later, it came calling.', 'policy-and-accountability', 'Alameda County District 2 ran on protecting the safety net, then passed a $19.3M AHS lifeline nobody would source. A look at what real accountability would look like, and where the ACT pilot fits.', '9 min read', '2026-06-29', 'Steph', 'Founder', null, ARRAY['this-is-not-charity-it-is-reconstruction', 'we-forgot-to-reinforce-the-foundations']::text[], 'retired', '[]'::jsonb, 17);
